# Round 54 -- part28 rows 78-112; 32 items
BATCH={
  (28, 78): {
   "topic": "posttermDatingError",
   "lead": "\u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0639\u0644\u062a \u00ab\u062d\u0627\u0645\u0644\u06af\u06cc \u0637\u0648\u0644\u200c\u06a9\u0634\u06cc\u062f\u0647\u00bb \u062f\u0631 \u062a\u0634\u062e\u06cc\u0635 \u0628\u0627\u0644\u06cc\u0646\u06cc\u060c \u062e\u0637\u0627 \u062f\u0631 \u062a\u0639\u06cc\u06cc\u0646 \u0633\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc (\u062a\u0627\u0631\u06cc\u062e EDC) \u0627\u0633\u062a\u060c \u0645\u062e\u0635\u0648\u0635\u0627\u064b \u0648\u0642\u062a\u06cc \u0645\u0646\u0633 \u0646\u0627\u0645\u0646\u0638\u0645 \u062f\u0627\u0634\u062a\u0647.",
   "interpretation": "\u0628\u0633\u06cc\u0627\u0631\u06cc \u0627\u0632 \u0645\u0648\u0627\u0631\u062f \u06af\u0632\u0627\u0631\u0634\u200c\u0634\u062f\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0637\u0648\u0644\u200c\u06a9\u0634\u06cc\u062f\u0647 \u062f\u0631 \u0648\u0627\u0642\u0639 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u0633 \u0627\u0632 \u062a\u0631\u0645 \u0648\u0627\u0642\u0639\u06cc \u0646\u06cc\u0633\u062a\u0646\u062f \u0628\u0644\u06a9\u0647 \u0646\u0627\u0634\u06cc \u0627\u0632 \u062e\u0637\u0627\u06cc \u062a\u062e\u0645\u06cc\u0646 \u062a\u0627\u0631\u06cc\u062e \u0632\u0627\u06cc\u0645\u0627\u0646 \u0628\u0631 \u0627\u0633\u0627\u0633 \u0645\u0646\u0633 \u0646\u0627\u0645\u0646\u0638\u0645 \u06cc\u0627 \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u062f\u06cc\u0631\u0647\u0646\u06af\u0627\u0645\u200c\u0627\u0646\u062f\u061b \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u06a9\u0644\u0627\u0633\u06cc\u06a9\u200c\u062a\u0631\u06cc\u0646 \u067e\u0627\u0633\u062e \u0627\u06cc\u0646 \u067e\u0631\u0633\u0634 \u00ab\u0628\u06cc\u200c\u062f\u0642\u062a\u06cc \u062f\u0631 \u062a\u0639\u06cc\u06cc\u0646 \u062a\u0627\u0631\u06cc\u062e EDC\u00bb \u0627\u0633\u062a \u0648 \u06a9\u0645\u0628\u0648\u062f \u0622\u0646\u0632\u06cc\u0645\u200c\u0647\u0627\u06cc \u062c\u0641\u062a\u06cc \u06cc\u0627 \u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0639\u0644\u0644 \u06a9\u0645\u200c\u062a\u0631 \u0634\u0627\u06cc\u0639\u200c\u0627\u0646\u062f.",
   "reasons": ["\u06a9\u0645\u0628\u0648\u062f \u0698\u0646\u06cc \u0633\u0648\u0644\u0641\u0627\u062a\u0627\u0632 \u062c\u0641\u062a\u06cc \u0639\u0644\u062a \u0646\u0627\u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0637\u0648\u0644\u200c\u06a9\u0634\u06cc\u062f\u0647 \u0627\u0633\u062a.", "\u062e\u0637\u0627\u06cc \u062a\u0639\u06cc\u06cc\u0646 \u062a\u0627\u0631\u06cc\u062e EDC \u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0639\u0644\u062a \u0627\u062f\u0639\u0627\u06cc \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0637\u0648\u0644\u200c\u06a9\u0634\u06cc\u062f\u0647 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u06a9\u0645\u0628\u0648\u062f \u0641\u0633\u0641\u0627\u062a\u0627\u0632 \u062c\u0641\u062a\u06cc \u0646\u06cc\u0632 \u0639\u0644\u062a \u0646\u0627\u062f\u0631 \u0648 \u06a9\u0645\u062a\u0631 \u062f\u06cc\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f \u0627\u0633\u062a.", "\u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u067e\u06cc\u0627\u0645\u062f \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u0633 \u0627\u0632 \u062a\u0631\u0645 \u0627\u0633\u062a \u0646\u0647 \u0639\u0644\u062a \u0634\u0627\u06cc\u0639 \u0622\u0646."],
  },
  (28, 79): {
   "topic": "pphSecondLinePreeclampsia",
   "lead": "\u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646\u0650 \u067e\u0633 \u0627\u0632-\u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0628\u0627 \u0631\u062d\u0645 \u0634\u0644\u0650 \u067e\u0627\u0633\u062e\u200c\u0646\u062f\u0647: \u0645\u06cc\u0632\u0648\u067e\u0631\u0648\u0633\u062a\u0648\u0644 \u0631\u06a9\u062a\u0627\u0644 \u0627\u0646\u062a\u062e\u0627\u0628 \u062e\u0637 \u062f\u0648\u0645 \u0627\u0645\u0646\u200c\u062a\u0631 \u0627\u0633\u062a (\u0627\u0631\u06af\u0648\u0646\u0648\u06cc\u0646 \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u0641\u0634\u0627\u0631 \u062e\u0648\u0646 \u0645\u0645\u0646\u0648\u0639).",
   "interpretation": "\u062f\u0631 \u0622\u062a\u0648\u0646\u06cc \u0631\u062d\u0645\u06cc \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646\u060c \u062e\u0637 \u0627\u0648\u0644 \u0627\u06a9\u0633\u06cc\u200c\u062a\u0648\u0633\u06cc\u0646 \u0627\u0633\u062a\u061b \u062e\u0637 \u062f\u0648\u0645 \u0628\u06cc\u0646 \u0645\u06cc\u0632\u0648\u067e\u0631\u0648\u0633\u062a\u0648\u0644 (PG E1)\u060c \u0645\u062a\u06cc\u0644\u200c\u0627\u0631\u06af\u0648\u0645\u062a\u0631\u06cc\u0646 (\u0627\u0631\u06af\u0648\u062a) \u0648 \u06a9\u0627\u0631\u0628\u0648\u067e\u0631\u0648\u0633\u062a (PGF2a) \u0627\u0633\u062a\u061b \u0648\u0644\u06cc \u0645\u062a\u06cc\u0644\u200c\u0627\u0631\u06af\u0648\u0645\u062a\u0631\u06cc\u0646 \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u0627\u062b\u0631 \u0642\u0648\u06cc \u0627\u0641\u0632\u0627\u06cc\u0634 \u0641\u0634\u0627\u0631 \u062f\u0631 \u0628\u06cc\u0645\u0627\u0631\u0627\u0646 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc/\u0641\u0634\u0627\u0631\u062e\u0648\u0646 \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a \u0648 \u0641\u0627\u06a9\u062a\u0648\u0631 \u0647\u0641\u062a \u0646\u0648\u062a\u0631\u06a9\u06cc\u0628 \u0628\u0631\u0627\u06cc \u0622\u062a\u0648\u0646\u06cc \u0646\u06cc\u0633\u062a \u0648 \u062a\u0631\u0627\u0646\u06a9\u0633\u0627\u0645\u06cc\u06a9 \u0627\u0633\u06cc\u062f \u0646\u0642\u0634 \u062a\u06a9\u0645\u06cc\u0644\u06cc \u0645\u062d\u062f\u0648\u062f \u062f\u0627\u0631\u062f\u061b \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u0645\u06cc\u0632\u0648\u067e\u0631\u0648\u0633\u062a\u0648\u0644 \u0631\u06a9\u062a\u0627\u0644 \u0627\u0646\u062a\u062e\u0627\u0628 \u0627\u06cc\u0646 \u06a9\u0644\u06cc\u062f \u0627\u0633\u062a.",
   "reasons": ["\u0645\u06cc\u0632\u0648\u067e\u0631\u0648\u0633\u062a\u0648\u0644 \u0631\u06a9\u062a\u0627\u0644 \u062e\u0637 \u062f\u0648\u0645 \u0627\u0645\u0646 \u062f\u0631 \u0628\u06cc\u0645\u0627\u0631 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0645\u062a\u06cc\u0644\u200c\u0627\u0631\u06af\u0648\u0645\u062a\u0631\u06cc\u0646 \u062f\u0631 \u0641\u0634\u0627\u0631\u062e\u0648\u0646/\u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a.", "\u062a\u0631\u0627\u0646\u06a9\u0633\u0627\u0645\u06cc\u06a9 \u0627\u0633\u06cc\u062f \u0646\u0642\u0634 \u06a9\u0645\u06a9\u06cc \u0627\u0633\u062a \u0646\u0647 \u062c\u0627\u06cc\u06af\u0632\u06cc\u0646 \u0627\u0635\u0644\u06cc \u0647\u06cc\u067e\u0648\u062a\u0648\u0646\u06cc\u06a9.", "\u0641\u0627\u06a9\u062a\u0648\u0631 \u0647\u0641\u062a \u0628\u0631\u0627\u06cc \u0622\u062a\u0648\u0646\u06cc \u06a9\u0627\u0631\u0628\u0631\u062f \u0646\u062f\u0627\u0631\u062f."],
  },
  (28, 80): {
   "topic": "amnioticFluidEmbolism",
   "lead": "\u062a\u0646\u06af\u06cc\u200c\u0646\u0641\u0633 \u0646\u0627\u06af\u0647\u0627\u0646\u06cc + \u0633\u06cc\u0627\u0646\u0648\u0632 + \u0647\u06cc\u067e\u0648\u062a\u0627\u0646\u0633\u06cc\u0648\u0646 + \u062a\u0634\u0646\u062c + \u0647\u0645\u0627\u0686\u0648\u0631\u06cc/\u0646\u0634\u062a \u0627\u0632 \u0622\u0646\u0698\u06cc\u0648\u06a9\u062a \u062f\u0631 \u0645\u0631\u062d\u0644\u0647\u0654 \u062f\u0648\u0645 \u0632\u0627\u06cc\u0645\u0627\u0646: \u0622\u0645\u0628\u0648\u0644\u06cc \u0645\u0627\u06cc\u0639 \u0622\u0645\u0646\u06cc\u0648\u062a\u06cc\u06a9 \u0622\u0645\u062f\u0647 \u0648 \u067e\u0627\u0633\u062e \u0627\u0648\u0644 \u062a\u0634\u062e\u06cc\u0635 \u0628\u0627\u0644\u06cc\u0646\u06cc \u0627\u0633\u062a.",
   "interpretation": "\u0622\u0645\u0628\u0648\u0644\u06cc \u0645\u0627\u06cc\u0639 \u0622\u0645\u0646\u06cc\u0648\u062a\u06cc\u06a9 \u062f\u0631 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0628\u0627 \u062a\u0631\u06a9\u06cc\u0628 \u0646\u0627\u06af\u0647\u0627\u0646\u06cc \u0627\u0636\u0637\u0631\u0627\u0628 \u062a\u0646\u0641\u0633\u06cc (\u062a\u0646\u06af\u06cc\u200c\u0646\u0641\u0633\u060c \u0633\u06cc\u0627\u0646\u0648\u0632\u060c \u0634\u0648\u06a9 \u0647\u06cc\u067e\u0648\u062a\u0627\u0646\u0633\u06cc\u0648\u0646) \u0648 \u00abDIC\u00bb (\u0647\u0645\u0648\u0631\u0627\u0698\u06cc/\u0646\u0634\u062a \u062e\u0648\u0646 \u0627\u0632 \u0645\u062d\u0644\u200c\u0647\u0627\u06cc \u062e\u0648\u0646\u06af\u06cc\u0631\u06cc) \u062d\u06cc\u0646 \u06cc\u0627 \u0628\u0644\u0627\u0641\u0627\u0635\u0644\u0647 \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0645\u06cc\u200c\u0622\u06cc\u062f\u061b \u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u062a\u0634\u0646\u062c \u0631\u0627 \u0645\u06cc\u200c\u062f\u0647\u062f \u0627\u0645\u0627 \u0633\u06cc\u0627\u0646\u0648\u0632 \u0648 \u0634\u0648\u06a9 \u0648 DIC \u0641\u0648\u0631\u06cc \u0631\u0627 \u0628\u0627 \u0627\u06cc\u0646 \u062d\u062c\u0645 \u0646\u0645\u06cc\u200c\u0633\u0627\u0632\u062f \u0648 \u0639\u0648\u0627\u0631\u0636 \u0627\u06a9\u0633\u06cc\u200c\u062a\u0648\u0633\u06cc\u0646 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0627\u06cc\u0646 \u062a\u0627\u0628\u0644\u0648 \u0631\u0627 \u0646\u0645\u06cc\u200c\u0633\u0627\u0632\u062f \u0648 \u067e\u0633\u062a\u200c\u067e\u0627\u0631\u062a\u0648\u0645 \u0647\u0645\u0648\u0631\u0627\u0698\u06cc \u0627\u0648\u0644\u06cc\u0647\u0654 \u0627\u06cc\u0646 \u062a\u0627\u0628\u0644\u0648\u06cc \u0627\u0646\u0641\u062c\u0627\u0631\u06cc \u062a\u0646\u0641\u0633\u06cc-\u0647\u0645\u0648\u062f\u06cc\u0646\u0627\u0645\u06cc\u06a9 \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0628\u0627 \u062a\u0634\u0646\u062c \u0622\u063a\u0627\u0632 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648\u0644\u06cc \u0634\u0648\u06a9 \u0648 \u0627\u0646\u0639\u0642\u0627\u062f \u062f\u0631\u0648\u0646\u200c\u0639\u0631\u0648\u0642\u06cc \u0645\u0646\u062a\u0634\u0631 \u0641\u0648\u0631\u06cc \u0631\u0627 \u0646\u0645\u06cc\u200c\u0622\u0648\u0631\u062f.", "\u0627\u06cc\u0646 \u0686\u0647\u0627\u0631\u06af\u0627\u0646\u0647 \u0628\u0627 \u0622\u0645\u0628\u0648\u0644\u06cc \u0645\u0627\u06cc\u0639 \u0622\u0645\u0646\u06cc\u0648\u062a\u06cc\u06a9 \u0628\u06cc\u0634\u200c\u062a\u0631\u06cc\u0646 \u062a\u0637\u0627\u0628\u0642 \u0631\u0627 \u062f\u0627\u0631\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0639\u0648\u0627\u0631\u0636 \u0627\u06a9\u0633\u06cc\u200c\u062a\u0648\u0633\u06cc\u0646 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0686\u0646\u06cc\u0646 \u062a\u0627\u0628\u0644\u0648\u06cc\u06cc \u0631\u0627 \u0646\u0645\u06cc\u200c\u0633\u0627\u0632\u062f.", "\u067e\u0633\u062a\u200c\u067e\u0627\u0631\u062a\u0648\u0645 \u0647\u0645\u0648\u0631\u0627\u0698\u06cc \u0627\u0648\u0644\u06cc\u0647 \u0627\u0632 \u0622\u062a\u0648\u0646\u06cc \u0645\u06cc\u200c\u0622\u06cc\u062f \u0648 \u0627\u06cc\u0646 \u062a\u0627\u0628\u0644\u0648 \u0631\u0627 \u0646\u0645\u06cc\u200c\u0633\u0627\u0632\u062f."],
  },
  (28, 81): {
   "topic": "leopoldFourth",
   "lead": "\u0645\u0627\u0646\u0648\u0631 \u0686\u0647\u0627\u0631\u0645 \u0644\u0626\u0648\u067e\u0648\u0644\u062f (\u0631\u0648 \u0628\u0647 \u067e\u0627\u0647\u0627\u06cc \u0645\u0627\u062f\u0631): \u062a\u0639\u06cc\u06cc\u0646 \u0641\u0644\u06a9\u0633\u06cc\u0648\u0646 \u06cc\u0627 \u0627\u06a9\u0633\u062a\u0627\u0646\u0633\u06cc\u0648\u0646 \u0633\u0631 \u062c\u0646\u06cc\u0646\u06cc \u062f\u0631 \u067e\u0631\u0632\u0627\u0646\u062a\u0627\u0633\u06cc\u0648\u0646 \u0633\u0641\u0627\u0644\u06cc\u06a9.",
   "interpretation": "\u0645\u0627\u0646\u0648\u0631 \u0686\u0647\u0627\u0631\u0645 \u0644\u0626\u0648\u067e\u0648\u0644\u062f \u0628\u0627 \u062e\u0648\u0627\u0646\u062f\u0646 \u062f\u0633\u062a\u200c\u0647\u0627\u06cc \u0645\u0639\u0627\u06cc\u0646\u0647\u200c\u06a9\u0646\u0646\u062f\u0647 \u062f\u0631 \u0637\u0631\u0641\u06cc\u0646 \u0644\u06af\u0646 \u0645\u0627\u062f\u0631 \u0648 \u0628\u0627 \u062d\u0631\u06a9\u062a \u0631\u0648 \u0628\u0647 \u067e\u0627\u06cc\u06cc\u0646\u060c \u062f\u0631 \u067e\u0631\u0632\u0627\u0646\u062a\u0627\u0633\u06cc\u0648\u0646 \u0633\u0641\u0627\u0644\u06cc\u06a9 \u0641\u0644\u06a9\u0633\u06cc\u0648\u0646 \u06cc\u0627 \u0627\u06a9\u0633\u062a\u0627\u0646\u0633\u06cc\u0648\u0646 \u0633\u0631 \u0648 \u062f\u0631\u062c\u0647\u0654 \u0646\u0632\u0648\u0644 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0646\u062f\u061b \u062a\u0639\u06cc\u06cc\u0646 \u0645\u062d\u0644 \u067e\u0634\u062a \u0648 \u0627\u0646\u062f\u0627\u0645\u200c\u0647\u0627 \u0645\u0631\u0628\u0648\u0637 \u0628\u0647 \u0645\u0627\u0646\u0648\u0631 \u062f\u0648\u0645 \u0648 \u062a\u0639\u06cc\u06cc\u0646 \u0633\u0641\u0627\u0644\u06cc\u06a9/\u0628\u0631\u06cc\u0686 \u0628\u0627 \u0645\u0627\u0646\u0648\u0631 \u0633\u0648\u0645/\u0627\u0648\u0644 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f \u0646\u0647 \u0686\u0647\u0627\u0631\u0645.",
   "reasons": ["\u062a\u0648\u0635\u06cc\u0641 \u0645\u0627\u0646\u0648\u0631 \u0686\u0647\u0627\u0631\u0645 (\u0631\u0648 \u0628\u0647 \u067e\u0627\u06cc\u06cc\u0646\u060c \u0641\u0644\u06a9\u0633\u06cc\u0648\u0646/\u0627\u06a9\u0633\u062a\u0627\u0646\u0633\u06cc\u0648\u0646 \u0633\u0631) \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0628\u0631\u06cc\u0686 \u06cc\u0627 \u0633\u0641\u0627\u0644\u06cc\u06a9 \u0628\u0648\u062f\u0646 \u0628\u0627 \u0645\u0627\u0646\u0648\u0631 \u0633\u0648\u0645/\u0627\u0648\u0644 \u062a\u0639\u06cc\u06cc\u0646 \u0645\u06cc\u200c\u0634\u0648\u062f \u0646\u0647 \u0686\u0647\u0627\u0631\u0645.", "\u0645\u062d\u0644 \u0627\u0646\u062f\u0627\u0645\u200c\u0647\u0627\u06cc \u062c\u0646\u06cc\u0646 \u0645\u0631\u0628\u0648\u0637 \u0628\u0647 \u0645\u0627\u0646\u0648\u0631 \u062f\u0648\u0645 \u0627\u0633\u062a.", "\u0631\u0648 \u0628\u0647 \u0635\u0648\u0631\u062a \u0627\u06cc\u0633\u062a\u0627\u062f\u0646 \u0628\u0631\u0627\u06cc \u0645\u0627\u0646\u0648\u0631 \u0686\u0647\u0627\u0631\u0645 \u0646\u06cc\u0633\u062a."],
  },
  (28, 82): {
   "topic": "postMolarNewPregBhcg",
   "lead": "\u0633\u0627\u0628\u0642\u0647\u0654 GTN \u062f\u0631\u0645\u0627\u0646\u200c\u0634\u062f\u0647 + \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0641\u0639\u0644\u06cc \u06f1\u06f3 \u0647\u0641\u062a\u0647: \u0647\u0645\u200c\u0627\u06a9\u0646\u0648\u0646 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0639\u0645\u0648\u0644 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f\u060c \u0627\u0645\u0627 \u062f\u0631 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0628\u0627\u06cc\u062f BHCG \u0631\u0627 \u062d\u062f\u0648\u062f \u06f6 \u0647\u0641\u062a\u0647 \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0686\u06a9 \u06a9\u0631\u062f \u062a\u0627 \u0639\u0648\u062f GTN \u0631\u062f \u0634\u0648\u062f.",
   "interpretation": "\u0647\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062c\u062f\u06cc\u062f \u067e\u0633 \u0627\u0632 \u0633\u0627\u0628\u0642\u0647\u0654 \u0645\u0648\u0644/GTN \u062e\u0637\u0631 \u0639\u0648\u062f \u0628\u06cc\u0645\u0627\u0631\u06cc \u062a\u0631\u0648\u0641\u0648\u0628\u0644\u0627\u0633\u062a\u06cc\u06a9 \u0631\u0627 \u0628\u0627 \u062e\u0648\u062f \u062f\u0627\u0631\u062f \u0648 \u0686\u0648\u0646 BHCG \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0641\u0639\u0644\u06cc \u00ab\u0637\u0628\u06cc\u0639\u06cc\u00bb \u0627\u0633\u062a\u060c \u0628\u0631\u0627\u06cc \u0631\u062f \u0639\u0648\u062f \u0628\u0627\u06cc\u062f \u067e\u0633 \u0627\u0632 \u062a\u06a9\u0645\u06cc\u0644 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc (\u0627\u0632 \u062c\u0645\u0644\u0647 \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u06a9\u0627\u0645\u0644\u0627\u064b \u0637\u0628\u06cc\u0639\u06cc) \u062a\u06cc\u062a\u0631 BHCG \u062d\u062f\u0648\u062f \u06f6 \u0647\u0641\u062a\u0647 \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0627\u0646\u062f\u0627\u0632\u0647 \u0634\u0648\u062f \u062a\u0627 \u0628\u0647 \u0631\u0648\u0634\u0646\u06cc \u0646\u0632\u0648\u0644 \u0622\u0646 \u062b\u0627\u0628\u062a \u0634\u0648\u062f\u061b \u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u0648\u06cc\u0698\u0647 \u0627\u0632 \u0622\u0646\u062f\u0648\u0645\u062a\u0631/\u0628\u0646\u062f \u0646\u0627\u0641 \u06cc\u0627 \u067e\u0631\u0632\u0647\u0627\u06cc \u06a9\u0648\u0631\u06cc\u0648\u0646\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0632\u0646\u062f\u0647 \u0627\u0642\u062a\u0636\u0627\u06cc \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f.",
   "reasons": ["\u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u067e\u0631\u0632\u0647\u0627\u06cc \u06a9\u0648\u0631\u06cc\u0648\u0646\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0632\u0646\u062f\u0647 \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a.", "\u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u06f6 \u0647\u0641\u062a\u0647 \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u062a\u0647\u0627\u062c\u0645\u06cc \u0648 \u063a\u06cc\u0631\u0636\u0631\u0648\u0631\u06cc \u0627\u0633\u062a.", "\u0627\u0646\u062f\u0627\u0632\u0647\u200c\u06af\u06cc\u0631\u06cc BHCG \u06f6 \u0647\u0641\u062a\u0647 \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u0627\u0632 \u0628\u0646\u062f \u0646\u0627\u0641 \u062d\u06cc\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062c\u0627\u06cc\u06af\u0627\u0647\u06cc \u0646\u062f\u0627\u0631\u062f."],
  },
  (28, 83): {
   "topic": "anemiaNormalIronElectrophoresis",
   "lead": "\u06a9\u0645\u200c\u062e\u0648\u0646\u06cc \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0633\u0648\u0645 \u0628\u0627 MCV \u067e\u0627\u06cc\u06cc\u0646 \u0648\u0644\u06cc \u0622\u0647\u0646 \u0648 \u0641\u0631\u06cc\u062a\u06cc\u0646 \u0637\u0628\u06cc\u0639\u06cc: \u0627\u0644\u06a9\u062a\u0631\u0648\u0641\u0648\u0631\u0632 \u0647\u0645\u0648\u06af\u0644\u0648\u0628\u06cc\u0646 \u0628\u0631\u0627\u06cc \u0631\u062f \u062a\u0627\u0644\u0627\u0633\u0645\u06cc/\u0647\u0645\u0648\u06af\u0644\u0648\u0628\u06cc\u0646\u0648\u067e\u0627\u062a\u06cc \u0628\u0639\u062f\u06cc \u0627\u0633\u062a.",
   "interpretation": "\u0647\u0646\u06af\u0627\u0645\u06cc \u06a9\u0647 \u06a9\u0645\u200c\u062e\u0648\u0646\u06cc \u0645\u06cc\u06a9\u0631\u0648\u0633\u06cc\u062a\u06cc\u06a9 \u0628\u0627 \u0634\u0648\u0627\u0647\u062f \u0622\u0647\u0646 \u0637\u0628\u06cc\u0639\u06cc (\u0622\u0647\u0646 \u0648 \u0641\u0631\u06cc\u062a\u06cc\u0646 \u0637\u0628\u06cc\u0639\u06cc) \u062f\u06cc\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u060c \u06a9\u0645\u200c\u062e\u0648\u0646\u06cc \u0641\u0642\u0631\u0622\u0647\u0646 \u200c\u0646\u06cc\u0633\u062a \u0648 \u0628\u0627\u06cc\u062f \u0647\u0645\u0648\u06af\u0644\u0648\u0628\u06cc\u0646\u0648\u067e\u0627\u062a\u06cc\u200c\u0647\u0627 (\u0645\u062b\u0644 \u062a\u0627\u0644\u0627\u0633\u0645\u06cc \u0645\u06cc\u0646\u0648\u0631\u060c \u0647\u0645\u0648\u06af\u0644\u0648\u0628\u06cc\u0646 E \u0648...) \u0631\u0627 \u0628\u0627 \u0627\u0644\u06a9\u062a\u0631\u0648\u0641\u0648\u0631\u0632 \u0647\u0645\u0648\u06af\u0644\u0648\u0628\u06cc\u0646 \u0628\u0631\u0631\u0633\u06cc \u06a9\u0631\u062f\u061b \u0634\u0645\u0627\u0631\u0634 \u0631\u062a\u06cc\u06a9\u0648\u0644\u0648\u0633\u06cc\u062a \u067e\u0627\u0633\u062e \u0628\u0647 \u062f\u0631\u0645\u0627\u0646/\u0647\u0645\u0648\u0644\u06cc\u0632 \u062a\u062e\u0645\u06cc\u0646\u06cc \u0631\u0627 \u0645\u06cc\u200c\u062f\u0647\u062f \u0627\u0645\u0627 \u0639\u0644\u062a \u0645\u06cc\u06a9\u0631\u0648\u0633\u06cc\u062a\u0648\u0632 \u0637\u0628\u06cc\u0639\u06cc \u0622\u0647\u0646 \u0631\u0627 \u062a\u0634\u062e\u06cc\u0635 \u0646\u0645\u06cc\u200c\u062f\u0647\u062f \u0648 \u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u0645\u063a\u0632 \u0627\u0633\u062a\u062e\u0648\u0627\u0646 \u0648 \u0641\u0648\u0644\u0627\u062a \u062f\u0631 \u067e\u0644\u0647\u0654 \u0628\u0639\u062f\u06cc \u0648 \u0628\u0631 \u0627\u0633\u0627\u0633 \u0634\u0631\u0627\u06cc\u0637 \u0639\u0645\u0644 \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["\u0634\u0645\u0627\u0631\u0634 \u0631\u062a\u06cc\u06a9\u0648\u0644\u0648\u0633\u06cc\u062a \u0633\u0628\u0628 \u0645\u06cc\u06a9\u0631\u0648\u0633\u06cc\u062a\u0648\u0632 \u0628\u0627 \u0622\u0647\u0646 \u0637\u0628\u06cc\u0639\u06cc \u0631\u0627 \u062a\u0639\u06cc\u06cc\u0646 \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f.", "\u0627\u0646\u062f\u0627\u0632\u0647\u200c\u06af\u06cc\u0631\u06cc \u0641\u0648\u0644\u0627\u062a \u062f\u0631 \u06a9\u0645\u200c\u062e\u0648\u0646\u06cc \u0645\u0627\u06a9\u0631\u0648\u0633\u06cc\u062a\u06cc\u06a9 \u06a9\u0627\u0631\u0628\u0631\u062f \u062f\u0627\u0631\u062f.", "\u0628\u0631\u0631\u0633\u06cc \u0645\u063a\u0632 \u0627\u0633\u062a\u062e\u0648\u0627\u0646 \u062f\u0631 \u0627\u06cc\u0646 \u0645\u0631\u062d\u0644\u0647 \u062a\u0647\u0627\u062c\u0645\u06cc \u0648 \u0632\u0648\u062f \u0627\u0633\u062a.", "\u0627\u0644\u06a9\u062a\u0631\u0648\u0641\u0648\u0631\u0632 \u0647\u0645\u0648\u06af\u0644\u0648\u0628\u06cc\u0646 \u0628\u0631\u0627\u06cc \u062a\u0645\u0627\u06cc\u0632 \u0647\u0645\u0648\u06af\u0644\u0648\u0628\u06cc\u0646\u0648\u067e\u0627\u062a\u06cc \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 84): {
   "topic": "epMethotrexateCriteria",
   "lead": "EP \u062a\u062b\u0628\u06cc\u062a\u200c\u0634\u062f\u0647\u0654 \u0622\u062f\u0646\u06a9\u0633\u0627\u0644 \u0628\u0627 \u062a\u0648\u062f\u0647\u0654 \u06f2 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631\u06cc\u060c HCG=\u06f3\u06f7\u06f0\u06f0\u060c \u0628\u062f\u0648\u0646 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u062f\u0627\u062e\u0644 \u0634\u06a9\u0645\u06cc \u0648 \u0639\u0644\u0627\u0626\u0645 \u067e\u0627\u06cc\u062f\u0627\u0631: \u0645\u0639\u06cc\u0627\u0631 \u062f\u0631\u0645\u0627\u0646 \u0637\u0628\u06cc \u0628\u0627 \u0645\u062a\u0648\u062a\u0631\u06a9\u0633\u0627\u062a \u062a\u0623\u0645\u06cc\u0646 \u0634\u062f\u0647 \u0627\u0633\u062a.",
   "interpretation": "\u0645\u062f\u06cc\u0631\u06cc\u062a \u0637\u0628\u06cc EP \u0628\u0627 \u0645\u062a\u0648\u062a\u0631\u06a9\u0633\u0627\u062a \u0645\u0646\u0627\u0633\u0628 \u0628\u06cc\u0645\u0627\u0631 \u067e\u0627\u06cc\u062f\u0627\u0631 \u0628\u0627 \u0627\u0646\u062f\u0627\u0632\u0647\u200c\u0647\u0627\u06cc \u06a9\u0648\u0686\u06a9 (\u062a\u0648\u062f\u0647\u0654 \u06a9\u0648\u0686\u06a9\u200c\u062a\u0631 \u0627\u0632 \u062d\u062f\u0648\u062f \u06f3\u066b\u06f5 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631)\u060c HCG \u0645\u0631\u0632 \u0635\u0639\u0648\u062f\u06cc \u0646\u0633\u0628\u062a\u0627\u064b \u06a9\u0646\u062a\u0631\u0644\u200c\u0634\u062f\u0647 (\u06a9\u0644\u0627\u0633\u06cc\u06a9\u0627\u064b \u06a9\u0645\u062a\u0631 \u0627\u0632 \u06f5\u06f0\u06f0\u06f0)\u060c \u0639\u062f\u0645 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0641\u0639\u0627\u0644 \u062f\u0627\u062e\u0644 \u0634\u06a9\u0645\u06cc \u0648 \u0639\u062f\u0645 \u0648\u062c\u0648\u062f \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062c\u0646\u06cc\u0646\u06cc \u062f\u0631 \u062a\u0648\u062f\u0647 \u0648 \u0627\u0644\u0628\u062a\u0647 \u062f\u0633\u062a\u0631\u0633\u06cc \u067e\u06cc\u06af\u06cc\u0631\u06cc \u0627\u0633\u062a\u061b \u0627\u06cc\u0646 \u0628\u06cc\u0645\u0627\u0631 \u0647\u0645\u0647\u0654 \u0645\u0639\u06cc\u0627\u0631\u0647\u0627 \u0631\u0627 \u062f\u0627\u0631\u062f \u0648 \u0645\u062f\u0627\u062e\u0644\u0647\u0654 \u062c\u0631\u0627\u062d\u06cc \u06cc\u0627 \u062f\u0631\u0645\u0627\u0646 \u0627\u0646\u062a\u0638\u0627\u0631\u06cc \u0628\u0627 \u062a\u06cc\u062a\u0631 \u0628\u0627\u0644\u0627\u062a\u0631 \u0627\u0632 \u062d\u062f \u0627\u0646\u062a\u0638\u0627\u0631 \u0645\u0646\u0627\u0633\u0628 \u0646\u06cc\u0633\u062a\u061b \u06a9\u0646\u062a\u0631\u0644 BHCG \u0647\u0631 \u06f4\u06f8 \u0633\u0627\u0639\u062a \u067e\u0627\u0633\u062e \u0628\u0647 HCG \u062d\u062f\u0648\u062f \u06f3\u06f7\u06f0\u06f0 \u0645\u0646\u0637\u0642\u06cc \u0646\u06cc\u0633\u062a \u0648 \u062a\u06a9\u0631\u0627\u0631 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062a\u0623\u062e\u06cc\u0631 \u0631\u0627 \u0627\u0641\u0632\u0648\u062f\u0647 \u0627\u0633\u062a.",
   "reasons": ["\u0686\u06a9 \u0633\u0644\u0627\u06cc\u0631 HCG \u062f\u0631 \u0627\u06cc\u0646 \u062a\u06cc\u062a\u0631 \u0648 \u06cc\u0627\u0641\u062a\u0647\u0654 \u0622\u062f\u0646\u06a9\u0633\u0627\u0644 \u06a9\u0627\u0647\u0634\u06cc \u062f\u0631\u0633\u062a \u0646\u06cc\u0633\u062a.", "\u062f\u0631\u0645\u0627\u0646 \u0627\u0646\u062a\u0638\u0627\u0631\u06cc \u062f\u0631 HCG \u06f3\u06f7\u06f0\u06f0 \u0628\u0627 \u062a\u0648\u062f\u0647\u0654 \u0622\u062f\u0646\u06a9\u0633\u0627\u0644 \u067e\u0630\u06cc\u0631\u0641\u062a\u0646\u06cc \u0646\u06cc\u0633\u062a.", "\u0645\u062a\u0648\u062a\u0631\u06a9\u0633\u0627\u062a \u062f\u0631 \u0627\u06cc\u0646 \u0645\u0648\u0642\u0639\u06cc\u062a \u0645\u0639\u06cc\u0627\u0631\u06cc \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062a\u06a9\u0631\u0627\u0631 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u06f4\u06f8 \u0633\u0627\u0639\u062a \u0628\u0639\u062f \u0641\u0642\u0637 \u0632\u0645\u0627\u0646 \u0631\u0627 \u0627\u0632\u062f\u0633\u062a \u0645\u06cc\u200c\u062f\u0647\u062f."],
  },
  (28, 85): {
   "topic": "pmbEvaluationHysteroscopy",
   "lead": "\u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632 \u06cc\u0627\u0626\u0633\u06af\u06cc (PMB) \u0628\u0627 \u0639\u0644\u0627\u06cc\u0645 \u062d\u06cc\u0627\u062a\u06cc \u067e\u0627\u06cc\u062f\u0627\u0631 \u0648 \u0628\u062f\u0648\u0646 \u0636\u0627\u06cc\u0639\u0647\u0654 \u0645\u0647/\u0633\u0631\u0648\u06cc\u06a9\u0633: \u0627\u0631\u062c\u0627\u0639 \u0628\u0647 \u0645\u062a\u062e\u0635\u0635 \u0628\u0627\u06cc\u062f \u0627\u0646\u062c\u0627\u0645 \u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0648 \u06a9\u0648\u0631\u062a\u0627\u0698 \u062a\u0634\u062e\u06cc\u0635\u06cc \u0628\u0627\u06cc\u062f \u0628\u0631 \u0627\u0648\u0631\u0698\u0627\u0646\u0633\u06cc\u200c\u0628\u0648\u062f\u0646 \u0628\u06cc\u0641\u062a\u062f.",
   "interpretation": "\u0647\u0631 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0627\u0632 \u062f\u0633\u062a\u06af\u0627\u0647 \u062a\u0646\u0627\u0633\u0644\u06cc \u067e\u0633 \u0627\u0632 \u06cc\u0627\u0626\u0633\u06af\u06cc \u062a\u0627 \u0631\u062f \u0628\u062f\u062e\u06cc\u0645\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0628\u0631\u0631\u0633\u06cc \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0686\u0648\u0646 \u0645\u0639\u0627\u06cc\u0646\u0647\u0654 \u0628\u0627\u0644\u06cc\u0646\u06cc \u0648\u0636\u0639\u06cc\u062a \u062d\u0641\u0631\u0647\u0654 \u0631\u062d\u0645 \u0631\u0627 \u0645\u0634\u062e\u0635 \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f\u060c \u0631\u0648\u0634 \u0645\u0633\u062a\u0642\u06cc\u0645\u200c\u062a\u0631 \u062a\u0634\u062e\u06cc\u0635\u06cc \u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0647\u0645\u0631\u0627\u0647 \u06a9\u0648\u0631\u062a\u0627\u0698/\u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u0627\u0633\u062a\u061b \u062a\u062c\u0648\u06cc\u0632 OCP \u06cc\u0627 \u0622\u06af\u0648\u0646\u06cc\u0633\u062a GnRH \u0628\u062f\u0648\u0646 \u062a\u0634\u062e\u06cc\u0635 \u0628\u06cc\u0645\u0627\u0631\u06cc \u0632\u0645\u06cc\u0646\u0647\u200c\u0627\u06cc \u0631\u0627 \u0645\u0627\u0633\u06a9 \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0628\u0647\u200c\u0639\u0646\u0648\u0627\u0646 \u0627\u0642\u062f\u0627\u0645 \u0627\u0648\u0644 \u0628\u062f\u0648\u0646 \u062a\u0634\u062e\u06cc\u0635 \u067e\u0627\u062a\u0648\u0644\u0648\u0698\u06cc \u0627\u0641\u0631\u0627\u0637 \u0627\u0633\u062a.",
   "reasons": ["\u062a\u062c\u0648\u06cc\u0632 OCP \u0628\u062f\u0648\u0646 \u0628\u0631\u0631\u0633\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0631\u0627 \u062a\u0623\u06cc\u06cc\u062f\u0634\u062f\u0647 \u0631\u062f \u0645\u06cc\u200c\u06a9\u0646\u062f.", "\u0622\u06af\u0648\u0646\u06cc\u0633\u062a GnRH \u0628\u0631\u0627\u06cc \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc PMB \u062f\u0631\u0645\u0627\u0646\u06cc-\u062a\u0634\u062e\u06cc\u0635\u06cc \u0646\u06cc\u0633\u062a.", "\u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc + \u06a9\u0648\u0631\u062a\u0627\u0698 \u062a\u0634\u062e\u06cc\u0635\u06cc \u0628\u0631\u0627\u06cc PMB \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0628\u062f\u0648\u0646 \u062a\u0634\u062e\u06cc\u0635 \u067e\u0627\u062a\u0648\u0644\u0648\u0698\u06cc \u0627\u0642\u062f\u0627\u0645 \u0627\u0648\u0644 \u0646\u06cc\u0633\u062a."],
  },
  (28, 86): {
   "topic": "severePreeclampsiaFeatures",
   "lead": "\u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0628\u0627 \u067e\u0644\u0627\u06a9\u062a \u06f5\u06f0 \u0647\u0632\u0627\u0631 + AST/ALT \u0628\u0627\u0644\u0627 + LDH \u06f1\u06f0\u06f0\u06f0 + \u067e\u0631\u0648\u062a\u0626\u06cc\u0646\u0648\u0631\u06cc: \u062a\u0635\u0648\u06cc\u0631 HELLP/\u0639\u0644\u0627\u06cc\u0645 \u0634\u062f\u06cc\u062f \u0648 \u0627\u0642\u062f\u0627\u0645 \u0642\u0637\u0639\u06cc \u0628\u0633\u062a\u0631\u06cc \u0648 \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc (\u0627\u06cc\u0646\u062f\u0627\u06a9\u0634\u0646 \u0628\u0627 \u0627\u06a9\u0633\u06cc\u200c\u062a\u0648\u0633\u06cc\u0646 \u062f\u0631 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0627\u0645\u06a9\u0627\u0646\u200c\u067e\u0630\u06cc\u0631).",
   "interpretation": "\u0647\u0645\u200c\u062e\u0648\u0627\u0646\u06cc \u062a\u0633\u062a\u200c\u0647\u0627\u06cc \u062e\u0648\u0646\u06cc (\u062a\u0631\u0648\u0645\u0628\u0648\u0633\u06cc\u062a\u0648\u067e\u0646\u06cc \u0634\u062f\u06cc\u062f\u060c AST/ALT \u0627\u0641\u0632\u0627\u06cc\u0634\u200c\u06cc\u0627\u0641\u062a\u0647\u060c LDH=\u06f1\u06f0\u06f0\u06f0 \u0646\u0634\u0627\u0646\u06af\u0631 \u0647\u0645\u0627\u0686\u0648\u0631\u06cc/\u0646\u06a9\u0631\u0648\u0632 \u06a9\u0628\u062f\u06cc) \u062f\u0631 \u06f3\u06f5 \u0647\u0641\u062a\u0647 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc\u060c \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0628\u0627 \u0639\u0644\u0627\u06cc\u0645 \u0634\u062f\u06cc\u062f/HELLP \u0631\u0627 \u0646\u0634\u0627\u0646 \u0645\u06cc\u200c\u062f\u0647\u062f \u0648 \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u2014 \u0646\u0647 \u0646\u06af\u0647\u200c\u062f\u0627\u0634\u062a\u0646 \u062a\u0627 \u06f3\u06f7 \u0647\u0641\u062a\u0647 \u06cc\u0627 \u0627\u0646\u062a\u0638\u0627\u0631 \u0628\u0627 \u0627\u0628\u0632\u0627\u0631\u0647\u0627\u06cc \u06a9\u0645\u06a9\u06cc \u0645\u062b\u0644 IVIG \u06cc\u0627 \u062a\u0632\u0631\u06cc\u0642 \u067e\u0644\u0627\u06a9\u062a \u0627\u0644\u06a9\u062a\u06cc\u0648 \u2014 \u0634\u0641\u0627\u0628\u062e\u0634 \u0648 \u062d\u06cc\u0627\u062a\u06cc \u0627\u0633\u062a\u061b \u062f\u0631 \u0628\u06cc\u0645\u0627\u0631 \u0628\u0627 \u0639\u0644\u0627\u0626\u0645 \u062d\u06cc\u0627\u062a\u06cc \u067e\u0627\u06cc\u062f\u0627\u0631\u060c \u0627\u06cc\u0646\u062f\u0627\u06a9\u0634\u0646 \u062e\u062a\u0645 \u062f\u0631 \u0646\u0632\u062f\u06cc\u06a9\u200c\u062a\u0631\u06cc\u0646 \u0632\u0645\u0627\u0646 \u0645\u0645\u06a9\u0646 \u062f\u0631\u0633\u062a \u0627\u0633\u062a.",
   "reasons": ["\u062c\u0645\u0639\u200c\u0622\u0648\u0631\u06cc \u0627\u062f\u0631\u0627\u0631 \u06f2\u06f4 \u0633\u0627\u0639\u062a\u0647 \u06cc\u0627 IVIG \u067e\u0631\u0648\u062a\u06a9\u0644 \u062f\u0631\u0645\u0627\u0646 HELLP \u0646\u06cc\u0633\u062a.", "\u062a\u0632\u0631\u06cc\u0642 \u067e\u0644\u0627\u06a9\u062a \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u0648 \u0646\u06af\u0647\u200c\u062f\u0627\u0634\u062a\u0646 \u062a\u0627 \u06f3\u06f7 \u0647\u0641\u062a\u0647 \u062f\u0631 \u0627\u06cc\u0646 \u0622\u0632\u0645\u0627\u06cc\u0634\u200c\u0647\u0627 \u0627\u0634\u062a\u0628\u0627\u0647 \u0627\u0633\u062a.", "\u0628\u0633\u062a\u0631\u06cc \u0648 \u062e\u062a\u0645 \u0628\u0627 \u0627\u06a9\u0633\u06cc\u200c\u062a\u0648\u0633\u06cc\u0646 \u062f\u0631 \u0627\u06cc\u0646 \u0648\u0636\u0639\u06cc\u062a \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0628\u062a\u0627\u0645\u062a\u0627\u0632\u0648\u0646 \u0648 \u0627\u0646\u062a\u0638\u0627\u0631 \u062a\u0627 \u06f3\u06f7 \u0647\u0641\u062a\u0647 \u062f\u0631 HELLP \u06a9\u0627\u0645\u0644 \u0627\u0634\u062a\u0628\u0627\u0647 \u0627\u0633\u062a."],
  },
  (28, 88): {
   "topic": "pmsDiagnosis",
   "lead": "\u0627\u0632 \u0648\u06cc\u0698\u06af\u06cc\u200c\u0647\u0627\u06cc \u0644\u0627\u0632\u0645 \u062a\u0634\u062e\u06cc\u0635 PMS: \u0628\u0647\u0628\u0648\u062f\u06cc \u0639\u0644\u0627\u06cc\u0645 \u062f\u0631 \u0686\u0646\u062f \u0631\u0648\u0632 \u0622\u063a\u0627\u0632\u06cc\u0646 \u0642\u0627\u0639\u062f\u06af\u06cc (\u067e\u0646\u062c\u0631\u0647\u0654 \u0641\u0648\u0644\u06cc\u06a9\u0648\u0644\u0627\u0631 \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0645\u062a \u0636\u0631\u0648\u0631\u06cc \u0627\u0633\u062a).",
   "interpretation": "\u062a\u0634\u062e\u06cc\u0635 \u0633\u0646\u062f\u0631\u0645 \u067e\u06cc\u0634 \u0627\u0632 \u0642\u0627\u0639\u062f\u06af\u06cc \u0628\u0627 \u062b\u0628\u062a \u0622\u06cc\u0646\u062f\u0647\u200c\u0646\u06af\u0631 \u0631\u0648\u0632\u0627\u0646\u0647\u0654 \u0639\u0644\u0627\u06cc\u0645 \u062f\u0631 \u062f\u0648 \u0633\u06cc\u06a9\u0644 \u0645\u062a\u0648\u0627\u0644\u06cc \u062a\u0623\u06cc\u06cc\u062f \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0645\u0639\u06cc\u0627\u0631\u0647\u0627\u06cc \u0645\u06a9\u0645\u0644 \u0634\u0627\u0645\u0644 \u062d\u0636\u0648\u0631 \u0639\u0644\u0627\u06cc\u0645 \u062f\u0631 \u0641\u0627\u0632 \u0644\u0648\u062a\u0626\u0627\u0644 \u062f\u06cc\u0631\u060c \u06a9\u0627\u0647\u0634 \u0646\u0627\u06af\u0647\u0627\u0646\u06cc \u0639\u0644\u0627\u06cc\u0645 \u0628\u0627 \u0634\u0631\u0648\u0639 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0648 \u0648\u062c\u0648\u062f \u0628\u0627\u0632\u0647\u0654 \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0645\u062a \u062d\u062f\u0627\u0642\u0644 \u0686\u0646\u062f \u0631\u0648\u0632 \u067e\u0633 \u0627\u0632 \u0634\u0631\u0648\u0639 \u0645\u0646\u0633 \u0648 \u0627\u062e\u062a\u0644\u0627\u0644 \u062f\u0631 \u06a9\u0627\u0631/\u062a\u062d\u0635\u06cc\u0644 \u0627\u0633\u062a\u061b \u0634\u0631\u0648\u0639 \u0639\u0644\u0627\u06cc\u0645 \u0627\u0632 \u0647\u0641\u062a\u0647\u0654 \u062f\u0648\u0645 \u0633\u06cc\u06a9\u0644 \u06cc\u0627 \u0639\u062f\u0645 \u062a\u062f\u0627\u062e\u0644 \u0628\u0627 \u06a9\u0627\u0631 \u06cc\u0627 \u0645\u062d\u062f\u0648\u062f\u06cc\u062a \u0628\u0647 \u06cc\u06a9 \u0633\u06cc\u06a9\u0644 \u0628\u0627 \u062a\u0639\u0631\u06cc\u0641 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0633\u0627\u0632\u06af\u0627\u0631 \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0634\u0631\u0648\u0639 \u0639\u0644\u0627\u06cc\u0645 \u0628\u0627\u06cc\u062f \u0645\u062d\u062f\u0648\u062f \u0628\u0647 \u0641\u0627\u0632 \u0644\u0648\u062a\u0626\u0627\u0644 \u0628\u0627\u0634\u062f \u0646\u0647 \u0647\u0641\u062a\u0647\u0654 \u062f\u0648\u0645 \u0633\u06cc\u06a9\u0644.", "\u0639\u062f\u0645 \u062a\u062f\u0627\u062e\u0644 \u0639\u0644\u0627\u06cc\u0645 \u0628\u0627 \u06a9\u0627\u0631\u060c \u0645\u0639\u06cc\u0627\u0631 \u0646\u0641\u06cc\u200c\u06a9\u0646\u0646\u062f\u0647 \u0627\u0633\u062a \u0646\u0647 \u062a\u0623\u06cc\u06cc\u062f\u06cc.", "\u06cc\u06a9 \u0633\u06cc\u06a9\u0644 \u0628\u0631\u0627\u06cc \u0633\u0627\u062e\u062a \u0627\u0644\u06af\u0648\u06cc \u062a\u06a9\u0631\u0627\u0631 PMS \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a (\u062d\u062f\u0627\u0642\u0644 \u062f\u0648 \u0633\u06cc\u06a9\u0644).", "\u0628\u0647\u0628\u0648\u062f\u06cc \u0637\u06cc \u0686\u0646\u062f \u0631\u0648\u0632 \u0627\u0648\u0644 \u0642\u0627\u0639\u062f\u06af\u06cc \u0645\u0639\u06cc\u0627\u0631 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 89): {
   "topic": "pregnancyBleedingFirstUsg",
   "lead": "\u062a\u0633\u062a \u0645\u062b\u0628\u062a \u0628\u0627\u0631\u062f\u0627\u0631\u06cc + \u062f\u0631\u062f \u0632\u06cc\u0631\u062f\u0644 \u0648 \u0644\u06a9\u0647\u200c\u0628\u06cc\u0646\u06cc: \u0627\u0648\u0644\u06cc\u0646 \u0642\u062f\u0645 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc (\u062a\u0631\u0627\u0646\u0633\u200c\u0648\u0627\u0698\u06cc\u0646\u0627\u0644) \u0628\u0631\u0627\u06cc \u062a\u0639\u06cc\u06cc\u0646 \u0645\u062d\u0644/\u0632\u0646\u062f\u0647 \u0628\u0648\u062f\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0648 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0622\u062f\u0646\u06a9\u0633 \u0627\u0633\u062a.",
   "interpretation": "\u062f\u0631 \u0627\u06cc\u0646 \u0627\u0644\u06af\u0648\u06cc \u0628\u0627\u0644\u06cc\u0646\u06cc\u060c \u062a\u0635\u0648\u06cc\u0631\u0628\u0631\u062f\u0627\u0631\u06cc \u0633\u0631\u06cc\u0639 \u062d\u0641\u0631\u0647\u0654 \u0631\u062d\u0645 \u0648 \u0622\u062f\u0646\u06a9\u0633 \u0647\u0645 \u0645\u062d\u0644 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc (\u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc vs EP) \u0648 \u0647\u0645 \u0648\u0636\u0639\u06cc\u062a \u0628\u0627\u0641\u062a \u062c\u0641\u062a/\u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u062e\u0644\u0641 \u062c\u0641\u062a \u0631\u0627 \u0645\u0634\u062e\u0635 \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0628\u0647 \u062f\u0627\u0645\u0646\u0647\u0654 \u062a\u0634\u062e\u06cc\u0635 \u067e\u0631\u062e\u0637\u0631 \u06a9\u0645\u06a9 \u0645\u06cc\u200c\u06a9\u0646\u062f\u061b \u062a\u06cc\u062a\u0631 \u0633\u0631\u06cc BHCG \u062f\u0631 \u0635\u0648\u0631\u062a \u0646\u0627\u062a\u0648\u0627\u0646 \u0628\u0648\u062f\u0646 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0627\u0632 \u062a\u0639\u06cc\u06cc\u0646 \u0645\u062d\u0644 \u0642\u062f\u0645 \u0628\u0639\u062f\u06cc \u0627\u0633\u062a\u060c \u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u0633\u0631\u0645 \u0628\u0631\u0627\u06cc \u062a\u0635\u0645\u06cc\u0645\u200c\u06af\u06cc\u0631\u06cc \u0641\u0648\u0631\u06cc \u0645\u0624\u06cc\u062f \u0646\u06cc\u0633\u062a \u0648 \u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0627\u0648\u0644\u06cc\u0647 \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0627\u0648\u0644\u06cc\u0646 \u0627\u0642\u062f\u0627\u0645 \u062f\u0631 \u0627\u06cc\u0646 \u0627\u0644\u06af\u0648\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062a\u06cc\u062a\u0631 \u0633\u0631\u06cc BHCG \u062f\u0631 \u0642\u062f\u0645 \u0628\u0639\u062f\u06cc \u062a\u0635\u0645\u06cc\u0645\u200c\u06af\u06cc\u0631\u06cc \u0642\u0631\u0627\u0631 \u0645\u06cc\u200c\u06af\u06cc\u0631\u062f.", "\u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u0633\u0631\u0645 \u0628\u0631\u0627\u06cc \u062a\u0634\u062e\u06cc\u0635 \u0645\u062d\u0644/\u0632\u0646\u062f\u0647 \u0628\u0648\u062f\u0646 \u0645\u0624\u06cc\u062f \u0646\u06cc\u0633\u062a.", "\u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u062f\u0631 \u0627\u06cc\u0646 \u0645\u0631\u062d\u0644\u0647 \u062a\u0647\u0627\u062c\u0645\u06cc \u0648 \u0646\u0627\u0645\u062a\u0639\u0627\u0631\u0641 \u0627\u0633\u062a."],
  },
  (28, 90): {
   "topic": "fetalMyocarditisCause",
   "lead": "\u0645\u06cc\u0648\u06a9\u0627\u0631\u062f\u06cc\u062a + \u0647\u06cc\u062f\u0631\u0648\u067e\u0633 \u062f\u0631 \u0627\u062a\u0648\u067e\u0633\u06cc \u062c\u0646\u06cc\u0646 \u0645\u0631\u062f\u0647: \u0627\u0632 \u0639\u0648\u0627\u0645\u0644 \u067e\u0627\u062a\u0648\u0698\u0646\u060c \u06a9\u0648\u06a9\u0633\u0627\u06a9\u06cc (\u0628\u0647\u200c\u062e\u0635\u0648\u0635 B) \u0631\u0627\u0628\u0637\u0647\u0654 \u06a9\u0644\u0627\u0633\u06cc\u06a9\u200c\u062a\u0631\u06cc \u0628\u0627 \u0645\u06cc\u0648\u06a9\u0627\u0631\u062f\u06cc\u062a \u062c\u0646\u06cc\u0646\u06cc \u062f\u0627\u0631\u062f.",
   "interpretation": "\u0645\u06cc\u0648\u06a9\u0627\u0631\u062f\u06cc\u062a \u062c\u0646\u06cc\u0646\u06cc/\u0647\u06cc\u062f\u0631\u0648\u067e\u0633\u060c \u0627\u0644\u06af\u0648\u06cc \u0639\u0641\u0648\u0646\u062a\u200c\u0647\u0627\u06cc \u0642\u0644\u0628\u06cc \u0627\u0633\u062a \u0648 \u0628\u06cc\u0646 \u0639\u0627\u0645\u0644\u200c\u0647\u0627\u06cc \u0627\u06cc\u0646 \u0641\u0647\u0631\u0633\u062a\u060c \u06a9\u0648\u06a9\u0633\u0627\u06a9\u06cc (\u0628\u0647\u200c\u0648\u06cc\u0698\u0647 \u0633\u0631\u0648\u062a\u0627\u06cc\u067e B) \u0639\u0644\u062a \u0634\u0646\u0627\u062e\u062a\u0647\u200c\u0634\u062f\u0647\u0654 \u0645\u06cc\u0648\u06a9\u0627\u0631\u062f\u06cc\u062a \u062f\u0631 \u0628\u0686\u0647\u200c\u0647\u0627 \u0648 \u062c\u0646\u06cc\u0646 \u0627\u0633\u062a\u061b CMV \u0648 \u062a\u0648\u06a9\u0633\u0648 \u0648 \u0645\u0627\u0644\u0627\u0631\u06cc\u0627 \u0647\u06cc\u062f\u0631\u0648\u067e\u0633 \u0631\u0627 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u0646\u062f \u0628\u062f\u0647\u0646\u062f \u0627\u0645\u0627 \u0644\u06cc\u0646\u06a9 \u06a9\u0644\u0627\u0633\u06cc\u06a9 \u0622\u0646\u200c\u0647\u0627 \u0628\u0647 \u0645\u06cc\u0648\u06a9\u0627\u0631\u062f\u06cc\u062a \u06a9\u0645\u200c\u0627\u062e\u062a\u0635\u0627\u0635\u06cc\u200c\u062a\u0631 \u062f\u0631 \u0627\u06cc\u0646 \u0686\u0627\u0631\u0686\u0648\u0628 \u0627\u0633\u062a.",
   "reasons": ["CMV \u0628\u06cc\u0634\u200c\u062a\u0631 \u0628\u0627 \u0647\u06cc\u062f\u0631\u0648\u067e\u0633/\u0633\u0645\u0639/\u0631\u06cc\u062a\u06cc\u0646 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a \u0646\u0647 \u0645\u06cc\u0648\u06a9\u0627\u0631\u062f\u06cc\u062a \u0628\u0631\u062c\u0633\u062a\u0647.", "\u062a\u0648\u06a9\u0633\u0648\u067e\u0627\u0644\u0633\u0645\u0648\u0632 \u0628\u0627 \u0633\u0647\u200c\u06af\u0627\u0646\u0647\u0654 \u06a9\u0644\u0627\u0633\u06cc\u06a9 \u06a9\u0644\u0633\u06cc\u0641\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u062f\u0627\u062e\u0644 \u062c\u0645\u062c\u0645\u0647\u200c\u0627\u06cc\u060c \u0647\u06cc\u062f\u0631\u0648\u0633\u0641\u0627\u0644\u06cc \u0648 \u06a9\u0648\u0631\u06cc\u0648\u0631\u062a\u06cc\u0646\u06cc\u062a \u0645\u06cc\u200c\u0622\u06cc\u062f.", "\u0645\u0627\u0644\u0627\u0631\u06cc\u0627 \u0628\u0627 \u06a9\u0645\u200c\u062e\u0648\u0646\u06cc \u0648 \u0637\u062d\u0627\u0644\u200c\u0628\u0632\u0631\u06af\u06cc \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a.", "\u06a9\u0648\u06a9\u0633\u0627\u06a9\u06cc B \u0628\u0627 \u0645\u06cc\u0648\u06a9\u0627\u0631\u062f\u06cc\u062a \u06a9\u0644\u0627\u0633\u06cc\u06a9 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 92): {
   "topic": "placentaAccretaSpectrum",
   "lead": "\u0646\u0641\u0648\u0630 \u067e\u0631\u0632\u0647\u0627\u06cc \u062c\u0641\u062a\u06cc \u0628\u0647 \u062f\u0627\u062e\u0644 \u0645\u06cc\u0648\u0645\u062a\u0631 (\u0646\u0647 \u0628\u0647 \u0633\u0631\u0648\u0632\u0627 \u0648 \u0646\u0647 \u0633\u0637\u062d\u06cc) \u062f\u0631 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc/\u062f\u0627\u067e\u0644\u0631 \u06f2\u06f0 \u0647\u0641\u062a\u0647: \u0646\u0627\u0645 \u062c\u0641\u062a \u0627\u06cc\u0646\u06a9\u0631\u062a\u0627.",
   "interpretation": "\u0637\u06cc\u0641 \u0686\u0633\u0628\u0646\u062f\u06af\u06cc \u062c\u0641\u062a \u0633\u0647 \u0639\u0645\u0642 \u062f\u0627\u0631\u062f: \u0622\u06a9\u0631\u062a\u0627 \u0686\u0633\u0628\u0646\u062f\u06af\u06cc \u0633\u0637\u062d\u06cc \u0628\u0647 \u0645\u06cc\u0648\u0645\u062a\u0631 \u0628\u062f\u0648\u0646 \u0646\u0641\u0648\u0630\u060c \u0627\u06cc\u0646\u06a9\u0631\u062a\u0627 \u0646\u0641\u0648\u0630 \u0628\u0647 \u062f\u0627\u062e\u0644 \u0645\u06cc\u0648\u0645\u062a\u0631 \u0648 \u067e\u0631\u06a9\u0631\u062a\u0627 \u0639\u0628\u0648\u0631 \u0627\u0632 \u0633\u0631\u0648\u0632\u0627 \u062a\u0627 \u0627\u0631\u06af\u0627\u0646\u200c\u0647\u0627\u06cc \u0645\u062c\u0627\u0648\u0631\u061b \u06af\u0632\u0627\u0631\u0634 \u00ab\u0646\u0641\u0648\u0630 \u0628\u0647 \u062f\u0627\u062e\u0644 \u0645\u06cc\u0648\u0645\u062a\u0631\u00bb \u062f\u0642\u06cc\u0642\u0627\u064b \u0627\u06cc\u0646\u06a9\u0631\u062a\u0627 \u0646\u0627\u0645\u06cc\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u067e\u0631\u06a9\u0631\u062a\u0627 \u062f\u0631 \u0635\u0648\u0631\u062a \u06af\u0630\u0631 \u0627\u0632 \u0633\u0631\u0648\u0632\u0627/\u0645\u062b\u0627\u0646\u0647 \u0648 \u0627\u06a9\u0631\u062a\u0627 \u062f\u0631 \u0635\u0648\u0631\u062a \u0686\u0633\u0628\u0646\u062f\u06af\u06cc \u0645\u062d\u062f\u0648\u062f \u0627\u0633\u062a \u0648 \u067e\u0631\u0648\u06cc\u0627 \u0645\u0648\u0636\u0648\u0639 \u0645\u0648\u0642\u0639\u06cc\u062a \u062c\u0641\u062a \u0627\u0633\u062a \u0646\u0647 \u0686\u0633\u0628\u0646\u062f\u06af\u06cc.",
   "reasons": ["\u0622\u06a9\u0631\u062a\u0627 \u0641\u0642\u0637 \u0686\u0633\u0628\u0646\u062f\u06af\u06cc \u0633\u0637\u062d\u06cc \u062c\u0641\u062a \u0628\u0647 \u0645\u06cc\u0648\u0645\u062a\u0631 \u0627\u0633\u062a \u0648 \u0646\u0641\u0648\u0630 \u0646\u062f\u0627\u0631\u062f.", "\u0646\u0641\u0648\u0630 \u0628\u0647 \u062f\u0627\u062e\u0644 \u0645\u06cc\u0648\u0645\u062a\u0631 \u062a\u0639\u0631\u06cc\u0641 \u0627\u06cc\u0646\u06a9\u0631\u062a\u0627 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u067e\u0631\u06a9\u0631\u062a\u0627 \u06cc\u0639\u0646\u06cc \u06af\u0630\u0631 \u0627\u0632 \u0633\u0631\u0648\u0632\u0627 \u0628\u0647 \u0633\u0645\u062a \u0627\u0631\u06af\u0627\u0646\u200c\u0647\u0627\u06cc \u0645\u062c\u0627\u0648\u0631.", "\u067e\u0631\u0648\u06cc\u0627 \u0648\u0636\u0639\u06cc\u062a \u0645\u0648\u0642\u0639\u06cc\u062a\u06cc \u062c\u0641\u062a \u0646\u0633\u0628\u062a \u0628\u0647 \u062f\u0647\u0627\u0646\u0647\u0654 \u0631\u062d\u0645 \u0627\u0633\u062a \u0646\u0647 \u0646\u0648\u0639 \u0633\u0646\u062f\u0631\u0645 \u0686\u0633\u0628\u0646\u062f\u06af\u06cc."],
  },
  (28, 93): {
   "topic": "genitalHerpesFeatures",
   "lead": "\u0632\u062e\u0645\u200c\u0647\u0627\u06cc \u0647\u0631\u067e\u0633 \u062a\u0646\u0627\u0633\u0644\u06cc \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0645\u062a\u0639\u062f\u062f\u060c \u062f\u0631\u062f\u0646\u0627\u06a9 \u0648 \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u0622\u062f\u0646\u0648\u067e\u0627\u062a\u06cc \u0627\u06cc\u0646\u06af\u0648\u06cc\u0646\u0627\u0644 \u062f\u0631\u062f\u0646\u0627\u06a9 \u0648 \u062e\u0648\u062f\u0645\u062d\u062f\u0648\u062f\u0634\u0648\u0646\u062f\u0647\u200c\u0627\u0646\u062f\u061b \u00ab\u0628\u062f\u0648\u0646 \u062f\u0631\u062f\u00bb \u0627\u0632 \u0645\u0634\u062e\u0635\u0627\u062a \u0622\u0646 \u0646\u06cc\u0633\u062a.",
   "interpretation": "\u0627\u0648\u0644\u06cc\u0646 \u062d\u0645\u0644\u0647\u0654 HSV \u0698\u0646\u06cc\u062a\u0627\u0644 \u0628\u0627 \u0636\u0627\u06cc\u0639\u0627\u062a \u062f\u0631\u062f\u0646\u0627\u06a9 \u0686\u0646\u062f\u06af\u0627\u0646\u0647\u0654 \u0648\u0632\u06cc\u06a9\u0648\u0644\u0627\u0631-\u0627\u0648\u0644\u0633\u0631\u0627\u062a\u06cc\u0648\u060c \u0622\u062f\u0646\u0648\u067e\u0627\u062a\u06cc \u062f\u0648\u0637\u0631\u0641\u0647\u0654 \u062f\u0631\u062f\u0646\u0627\u06a9 \u0627\u06cc\u0646\u06af\u0648\u06cc\u0646\u0627\u0644 \u0648 \u0633\u06cc\u0631 \u062e\u0648\u062f\u0645\u062d\u062f\u0648\u062f\u0634\u0648\u0646\u062f\u0647\u200c\u0627\u06cc \u0637\u06cc \u06f2-\u06f3 \u0647\u0641\u062a\u0647 \u0645\u06cc\u200c\u0622\u06cc\u062f\u061b \u0632\u062e\u0645 \u0628\u062f\u0648\u0646 \u062f\u0631\u062f \u0645\u0634\u062e\u0635\u0647\u0654 \u0633\u06cc\u0641\u0644\u06cc\u0633 \u0627\u0633\u062a \u0646\u0647 \u0647\u0631\u067e\u0633\u060c \u0648 \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u06af\u0632\u06cc\u0646\u0647\u200c\u0627\u06cc \u06a9\u0647 \u062f\u0631 \u0641\u0647\u0631\u0633\u062a \u0646\u0645\u06cc\u200c\u06af\u0646\u062c\u062f \u00ab\u0628\u062f\u0648\u0646 \u062f\u0631\u062f\u00bb \u0627\u0633\u062a.",
   "reasons": ["\u0645\u062a\u0639\u062f\u062f \u0628\u0648\u062f\u0646 \u0632\u062e\u0645\u200c\u0647\u0627 \u0627\u0632 \u0645\u0634\u062e\u0635\u0627\u062a \u06a9\u0644\u0627\u0633\u06cc\u06a9 \u0647\u0631\u067e\u0633 \u0698\u0646\u06cc\u062a\u0627\u0644 \u0627\u0633\u062a.", "\u0628\u062f\u0648\u0646 \u062f\u0631\u062f \u0628\u0648\u062f\u0646 \u0645\u0634\u062e\u0635\u0647\u0654 \u0633\u06cc\u0641\u0644\u06cc\u0633 \u0627\u0633\u062a \u0646\u0647 \u0647\u0631\u067e\u0633\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d (\u0627\u0633\u062a\u062b\u0646\u0627).", "\u0622\u062f\u0646\u0648\u067e\u0627\u062a\u06cc \u062f\u0631\u062f\u0646\u0627\u06a9 \u0627\u06cc\u0646\u06af\u0648\u06cc\u0646\u0627\u0644 \u0627\u0632 \u0645\u0634\u062e\u0635\u0627\u062a \u0627\u0648\u0644\u06cc\u0646 \u062d\u0645\u0644\u0647 \u0627\u0633\u062a.", "\u062e\u0648\u062f\u0645\u062d\u062f\u0648\u062f\u0634\u0648\u0646\u062f\u0647 \u0628\u0648\u062f\u0646 \u0646\u06cc\u0632 \u0628\u0627 \u062f\u0648\u0631\u0647\u0654 \u0637\u0628\u06cc\u0639\u06cc HSV \u0633\u0627\u0632\u06af\u0627\u0631 \u0627\u0633\u062a."],
  },
  (28, 95): {
   "topic": "contraceptionMenorrhagiaMigraine",
   "lead": "\u0645\u06cc\u06af\u0631\u0646 \u06a9\u0644\u0627\u0633\u06cc\u06a9 (\u0622\u0648\u0631\u06cc-\u062f\u0627\u0631) + \u0645\u0646\u0648\u0631\u0627\u0698\u06cc \u0648 \u062f\u06cc\u0633\u0645\u0646\u0648\u0631\u0647 \u062f\u0631 \u06f3\u06f8 \u0633\u0627\u0644\u0647: \u0645\u06cc\u0631\u0646\u0627 (IUD \u0644\u0648\u0648\u0646\u0648\u0631\u0698\u0633\u062a\u0631\u0648\u0644) \u0628\u0647\u062a\u0631\u06cc\u0646 \u067e\u0627\u0633\u062e \u0627\u0633\u062a \u2014 \u0628\u0631 \u062e\u0644\u0627\u0641 OCP\u060c \u062f\u0631 \u0645\u06cc\u06af\u0631\u0646 \u0628\u0627 \u0627\u0648\u0631\u0627\u06cc \u0645\u062d\u062f\u0648\u062f \u0646\u06cc\u0633\u062a \u0648 \u0645\u0646\u0648\u0631\u0627\u0698\u06cc \u0631\u0627 \u0647\u0645 \u062f\u0631\u0645\u0627\u0646 \u0645\u06cc\u200c\u06a9\u0646\u062f.",
   "interpretation": "\u062f\u0631 \u0645\u06cc\u06af\u0631\u0646 \u0628\u0627 \u0639\u0644\u0627\u0626\u0645 \u0639\u0635\u0628\u06cc \u06af\u0630\u0631\u0627 (\u0622\u0626\u0648\u0631\u0627) \u0645\u0635\u0631\u0641 \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u062a\u0631\u06a9\u06cc\u0628\u06cc \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u062e\u0637\u0631 \u0633\u06a9\u062a\u0647\u0654 \u0627\u06cc\u0633\u06a9\u0645\u06cc\u06a9 \u0646\u0633\u0628\u06cc \u062a\u0648\u0635\u06cc\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 OCP \u06af\u0632\u06cc\u0646\u0647\u0654 \u0645\u0646\u0627\u0633\u0628\u06cc \u0646\u06cc\u0633\u062a\u061b \u0645\u06cc\u0631\u0646\u0627 \u0628\u0627 \u067e\u0631\u0648\u0698\u0633\u062a\u06cc\u0646 \u0645\u0648\u0636\u0639\u06cc\u060c \u0647\u0645 \u0645\u0646\u0648\u0631\u0627\u0698\u06cc \u0631\u0627 \u0628\u0647\u200c\u062e\u0648\u0628\u06cc \u062f\u0631\u0645\u0627\u0646 \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0647\u0645 \u062e\u0637\u0631 \u062a\u0631\u0648\u0645\u0628\u0648\u0632 \u0633\u06cc\u0633\u062a\u0645\u06cc\u06a9 \u0646\u062f\u0627\u0631\u062f \u0648 \u062f\u0631 \u0645\u06cc\u06af\u0631\u0646 \u0622\u0631\u06cc \u062f\u0627\u0631 \u0646\u06cc\u0632 \u0645\u062c\u0627\u0632 \u0627\u0633\u062a\u061b \u0631\u0648\u0634 \u0645\u06a9\u0627\u0646\u06cc\u06a9\u06cc \u06a9\u0627\u0646\u062f\u0648\u0645 \u0628\u0647 \u0645\u0646\u0648\u0631\u0627\u0698\u06cc \u06a9\u0645\u06a9\u06cc \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u062a\u0648\u0628\u06a9\u062a\u0648\u0645\u06cc \u062a\u063a\u06cc\u06cc\u0631 \u063a\u06cc\u0631\u0642\u0627\u0628\u0644\u200c\u0628\u0631\u06af\u0634\u062a \u0628\u0631\u0627\u06cc \u06a9\u0633\u06cc \u0627\u0633\u062a \u06a9\u0647 \u0647\u0646\u0648\u0632 \u0641\u0631\u0627\u06cc\u0646\u062f \u062a\u0635\u0645\u06cc\u0645\u200c\u06af\u06cc\u0631\u06cc \u0631\u0627 \u0628\u0631\u0627\u06cc \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0642\u0637\u0639 \u0646\u06a9\u0631\u062f\u0647 \u0627\u0633\u062a.",
   "reasons": ["OCP \u062f\u0631 \u0645\u06cc\u06af\u0631\u0646 \u0628\u0627 \u0622\u0631\u06cc \u062a\u0648\u0635\u06cc\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0645\u0646\u0648\u0631\u0627\u0698\u06cc \u0631\u0627 \u0646\u06cc\u0632 \u067e\u0646\u0647\u0627\u0646 \u0645\u06cc\u200c\u06a9\u0646\u062f.", "\u06a9\u0627\u0646\u062f\u0648\u0645 \u0639\u0644\u0627\u0648\u0647 \u0628\u0631 \u0646\u0631\u062e \u0646\u0627\u06a9\u0627\u0645\u06cc \u0628\u0627\u0644\u0627\u062a\u0631\u060c \u0628\u0647 \u062f\u0631\u0645\u0627\u0646 \u0645\u0646\u0648\u0631\u0627\u0698\u06cc \u06a9\u0645\u06a9\u06cc \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f.", "IUD \u0645\u06cc\u0631\u0646\u0627 \u0647\u0645 \u0627\u062b\u0631 \u06a9\u0627\u0647\u0646\u062f\u0647\u0654 \u0645\u0646\u0648\u0631\u0627\u0698\u06cc \u0631\u0627 \u062f\u0627\u0631\u062f \u0647\u0645 \u062f\u0631 \u0645\u06cc\u06af\u0631\u0646 \u0628\u0627 \u0622\u0631\u06cc \u0645\u062c\u0627\u0632\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062a\u0648\u0628\u06a9\u062a\u0648\u0645\u06cc \u062a\u0635\u0645\u06cc\u0645 \u062f\u0627\u0626\u0645\u06cc \u0627\u0633\u062a \u0648 \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646 \u0648 \u0627\u06cc\u0646 \u0633\u0627\u0628\u0642\u0647\u0654 \u0646\u0627\u06a9\u0627\u0645\u0644 \u0645\u0633\u06cc\u0631 \u0645\u0646\u0637\u0642\u06cc\u200c\u062a\u0631 \u0646\u06cc\u0633\u062a."],
  },
  (28, 96): {
   "topic": "gdmRiskFactors",
   "lead": "\u0641\u0627\u06a9\u062a\u0648\u0631\u0647\u0627\u06cc \u062e\u0637\u0631 GDM \u0634\u0627\u0645\u0644 \u06af\u0644\u0648\u06a9\u0648\u0632\u0648\u0631\u06cc \u0645\u062f\u0627\u0648\u0645\u060c \u0645\u0635\u0631\u0641 \u0637\u0648\u0644\u0627\u0646\u06cc \u06a9\u0648\u0631\u062a\u06cc\u06a9\u0648\u0627\u0633\u062a\u0631\u0648\u0626\u06cc\u062f \u0648 \u0633\u0627\u0628\u0642\u0647\u0654 \u0634\u062e\u0635\u06cc GDM \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u0633\u0646 \u0632\u06cc\u0631 \u06f3\u06f0 \u0627\u0641\u0632\u0627\u06cc\u0634 \u062e\u0637\u0631 \u0646\u06cc\u0633\u062a.",
   "interpretation": "\u0633\u0646 \u0628\u0627\u0644\u0627\u06cc \u06f2\u06f5-\u06f3\u06f0 \u0633\u0627\u0644 \u062e\u0648\u062f \u06cc\u06a9 \u0639\u0627\u0645\u0644 \u062e\u0637\u0631 \u0627\u0633\u062a \u0648\u0644\u06cc \u00ab\u06a9\u0645\u200c\u062a\u0631 \u0627\u0632 \u06f3\u06f0\u00bb \u0628\u0647\u200c\u0645\u0639\u0646\u0627\u06cc \u0646\u0628\u0648\u062f \u0622\u0646 \u0633\u0646 \u0628\u0627\u0644\u0627\u06cc \u062d\u062f \u0622\u0633\u062a\u0627\u0646\u0647 \u0627\u0633\u062a \u0648 \u0646\u0628\u0627\u06cc\u062f \u0628\u0647\u200c\u0639\u0646\u0648\u0627\u0646 \u0631\u06cc\u0633\u06a9 \u0628\u0631\u0627\u06cc GDM \u0644\u062d\u0627\u0638 \u0634\u0648\u062f\u061b \u062f\u0631 \u0645\u0642\u0627\u0628\u0644 \u06af\u0644\u0648\u06a9\u0648\u0632\u0648\u0631\u06cc \u0645\u062f\u0627\u0648\u0645 (\u062a\u062c\u0627\u0648\u0632 \u0627\u0632 \u0622\u0633\u062a\u0627\u0646\u0647\u0654 \u06a9\u0644\u06cc\u0648\u06cc)\u060c \u062f\u0631\u0645\u0627\u0646\u200c\u0647\u0627\u06cc \u06a9\u0648\u0631\u062a\u06cc\u06a9\u0648\u0627\u0633\u062a\u0631\u0648\u0626\u06cc\u062f (\u0627\u062e\u062a\u0644\u0627\u0644 \u0645\u062a\u0627\u0628\u0648\u0644\u06cc\u0633\u0645 \u0642\u0646\u062f) \u0648 \u0633\u0627\u0628\u0642\u0647\u0654 \u0634\u062e\u0635\u06cc \u062f\u06cc\u0627\u0628\u062a \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u06cc\u0634\u06cc\u0646 \u0647\u0645\u0647 \u0648\u0627\u0636\u062d\u0627\u064b \u062e\u0637\u0631 \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u0646\u062f.",
   "reasons": ["\u06af\u0644\u0648\u06a9\u0648\u0632\u0648\u0631\u06cc \u0645\u062f\u0627\u0648\u0645 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0646\u0634\u0627\u0646\u0647\u0654 \u0627\u062d\u062a\u0645\u0627\u0644 GDM \u0648 \u06cc\u06a9\u06cc \u0627\u0632 \u0641\u0627\u06a9\u062a\u0648\u0631\u0647\u0627\u06cc \u062e\u0637\u0631 \u0627\u0633\u062a.", "\u0645\u0635\u0631\u0641 \u0637\u0648\u0644\u0627\u0646\u06cc \u06a9\u0648\u0631\u062a\u06cc\u06a9\u0648\u0627\u0633\u062a\u0631\u0648\u0626\u06cc\u062f \u062e\u0637\u0631 \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f.", "\u0633\u0646 \u06a9\u0645\u200c\u062a\u0631 \u0627\u0632 \u06f3\u06f0 \u0641\u0627\u06a9\u062a\u0648\u0631 \u062e\u0637\u0631 \u0646\u06cc\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d (\u0627\u0633\u062a\u062b\u0646\u0627).", "\u0633\u0627\u0628\u0642\u0647\u0654 \u062f\u06cc\u0627\u0628\u062a \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0642\u0628\u0644\u06cc \u0627\u0632 \u0642\u0648\u06cc\u200c\u062a\u0631\u06cc\u0646 \u0631\u06cc\u0633\u06a9\u200c\u0647\u0627\u0633\u062a."],
  },
  (28, 97): {
   "topic": "menopauseAgeFactor",
   "lead": "\u0627\u0632 \u0645\u06cc\u0627\u0646 \u0627\u06cc\u0646 \u0641\u0647\u0631\u0633\u062a\u060c \u0645\u0647\u0645\u200c\u062a\u0631\u06cc\u0646 \u062a\u0639\u06cc\u06cc\u0646\u200c\u06a9\u0646\u0646\u062f\u0647\u0654 \u0633\u0646 \u0645\u0646\u0648\u067e\u0648\u0632 \u0698\u0646\u062a\u06cc\u06a9 \u0627\u0633\u062a (\u0627\u0644\u06af\u0648\u06cc \u062e\u0627\u0646\u0648\u0627\u062f\u06af\u06cc).",
   "interpretation": "\u0633\u0646 \u0637\u0628\u06cc\u0639\u06cc \u06cc\u0627\u0626\u0633\u06af\u06cc \u062a\u062d\u062a \u062a\u0623\u062b\u06cc\u0631 \u0639\u0648\u0627\u0645\u0644 \u0698\u0646\u062a\u06cc\u06a9\u06cc \u0627\u0633\u062a \u0648 \u062f\u0631 \u062f\u062e\u062a\u0631\u0647\u0627 \u0628\u0627 \u0645\u0627\u062f\u0631\u0627\u0646/\u062e\u0648\u0627\u0647\u0631\u0627\u0646 \u06cc\u0627\u0626\u0633\u0647\u200c\u0631\u0633\u06cc\u062f\u0647\u200c\u062a\u0631 \u0639\u0645\u0648\u0645\u0627\u064b \u0647\u0645\u200c\u0633\u0648 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u0633\u0646 \u0645\u0646\u0627\u0631\u06a9\u060c \u067e\u0627\u0631\u06cc\u062a\u0647 \u06cc\u0627 \u0648\u0636\u0639\u06cc\u062a \u0627\u062c\u062a\u0645\u0627\u0639\u06cc-\u0627\u0642\u062a\u0635\u0627\u062f\u06cc \u0627\u062b\u0631\u0627\u062a \u0636\u0639\u06cc\u0641\u200c\u062a\u0631 \u0648 \u0645\u062a\u063a\u06cc\u0631\u062a\u0631\u06cc \u062f\u0627\u0631\u0646\u062f \u0648 \u0645\u0635\u0631\u0641 \u0633\u06cc\u06af\u0627\u0631 \u0627\u0632 \u0628\u0642\u06cc\u0647 \u0627\u062b\u0631 \u0645\u0647\u0645\u06cc \u062f\u0627\u0631\u062f \u0648\u0644\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0641\u0647\u0631\u0633\u062a \u0698\u0646\u062a\u06cc\u06a9 \u0642\u0648\u06cc\u200c\u062a\u0631\u06cc\u0646 \u0627\u0633\u062a.",
   "reasons": ["\u0633\u0646 \u0634\u0631\u0648\u0639 \u0645\u0646\u0627\u0631\u06a9 \u062a\u0639\u06cc\u06cc\u0646\u200c\u06a9\u0646\u0646\u062f\u0647\u0654 \u0627\u0635\u0644\u06cc \u0633\u0646 \u06cc\u0627\u0626\u0633\u06af\u06cc \u0646\u06cc\u0633\u062a.", "\u067e\u0627\u0631\u06cc\u062a\u0647 \u0627\u062b\u0631 \u0642\u0627\u0628\u0644\u200c\u062a\u0648\u062c\u0647 \u0648 \u0646\u0627\u0686\u06cc\u0632 \u0628\u0631 \u0633\u0646 \u0645\u0646\u0648\u067e\u0648\u0632 \u0646\u062f\u0627\u0631\u062f.", "\u0698\u0646\u062a\u06cc\u06a9 \u0642\u0648\u06cc\u200c\u062a\u0631\u06cc\u0646 \u0639\u0627\u0645\u0644 \u062f\u0631 \u0627\u06cc\u0646 \u0641\u0647\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0648\u0636\u0639\u06cc\u062a \u0627\u062c\u062a\u0645\u0627\u0639\u06cc-\u0627\u0642\u062a\u0635\u0627\u062f\u06cc \u0641\u0642\u0637 \u0627\u062b\u0631 \u063a\u06cc\u0631\u0645\u0633\u062a\u0642\u06cc\u0645 \u0648 \u0627\u0646\u062f\u06a9\u06cc \u062f\u0627\u0631\u062f."],
  },
  (28, 98): {
   "topic": "infertilityEvalFirstStep",
   "lead": "\u062f\u0631 \u0646\u0627\u0632\u0627\u06cc\u06cc \u0627\u0648\u0644\u06cc\u0647\u0654 \u06cc\u06a9\u200c\u0633\u0627\u0644\u0647\u060c \u0627\u0648\u0644\u06cc\u0646 \u0642\u062f\u0645 \u06a9\u0644\u06cc\u0650 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0632\u0648\u062c\u060c \u0634\u0631\u062d\u200c\u062d\u0627\u0644 \u062f\u0642\u06cc\u0642 \u0648 \u0645\u0639\u0627\u06cc\u0646\u0647\u0654 \u0641\u06cc\u0632\u06cc\u06a9\u06cc \u0647\u0631 \u062f\u0648 \u0646\u0641\u0631 \u0627\u0633\u062a \u0648 \u0633\u067e\u0633 \u062a\u0633\u062a\u200c\u0647\u0627\u06cc \u067e\u0627\u06cc\u0647 (\u0627\u0633\u067e\u0631\u0645\u0648\u06af\u0631\u0627\u0645...) \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "interpretation": "\u06a9\u0627\u0631\u0622\u067e \u0646\u0627\u0632\u0627\u06cc\u06cc \u0628\u0627 \u06af\u0631\u0641\u062a\u0646 \u0634\u0631\u062d\u200c\u062d\u0627\u0644 \u06a9\u0627\u0645\u0644 (\u0633\u0627\u0628\u0642\u0647\u0654 \u0642\u0627\u0639\u062f\u06af\u06cc\u060c \u062c\u0631\u0627\u062d\u06cc \u0644\u06af\u0646\u060c \u0639\u0641\u0648\u0646\u062a\u060c \u0627\u0644\u06af\u0648\u06cc \u0646\u0632\u062f\u06cc\u06a9\u06cc) \u0648 \u0645\u0639\u0627\u06cc\u0646\u0647\u0654 \u0641\u06cc\u0632\u06cc\u06a9\u06cc \u0647\u0631 \u062f\u0648 \u0632\u0648\u062c \u0622\u063a\u0627\u0632 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0628\u0631 \u0627\u0633\u0627\u0633 \u0622\u0646 \u0628\u0631\u0627\u06cc \u0645\u0631\u062f \u0627\u0633\u067e\u0631\u0645\u0648\u06af\u0631\u0627\u0645 \u0648 \u0628\u0631\u0627\u06cc \u0632\u0646 \u0633\u0627\u06cc\u0631 \u062a\u0633\u062a\u200c\u0647\u0627 \u0628\u0631\u0646\u0627\u0645\u0647\u200c\u0631\u06cc\u0632\u06cc \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u0634\u0631\u0648\u0639 \u0628\u0627 \u062a\u0633\u062a\u200c\u0647\u0627\u06cc \u0628\u0631\u0686\u0633\u0628\u200c\u062f\u0627\u0631 \u0645\u062b\u0644 \u0622\u0632\u0645\u0627\u06cc\u0634 \u0627\u0633\u067e\u0631\u0645 \u06cc\u0627 BBT \u06cc\u0627 HSG \u0628\u062f\u0648\u0646 \u067e\u0627\u06cc\u0647\u200c\u0631\u06cc\u0632\u06cc \u062a\u0627\u0631\u06cc\u062e\u06cc-\u0628\u0627\u0644\u06cc\u0646\u06cc\u060c \u0646\u0638\u0645 \u0645\u0646\u0637\u0642\u06cc \u06a9\u0627\u0631\u0622\u067e \u0631\u0627 \u0645\u06cc\u200c\u0634\u06a9\u0646\u062f.",
   "reasons": ["\u0634\u0631\u062d\u200c\u062d\u0627\u0644 \u0648 \u0645\u0639\u0627\u06cc\u0646\u0647\u0654 \u0641\u06cc\u0632\u06cc\u06a9\u06cc \u0627\u0648\u0644\u06cc\u0646 \u0642\u062f\u0645 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0627\u0633\u067e\u0631\u0645\u0648\u06af\u0631\u0627\u0645 \u0647\u0645\u0632\u0645\u0627\u0646/\u0628\u0639\u062f \u0627\u0632 \u062a\u0627\u0631\u06cc\u062e \u0627\u0648\u0644\u06cc\u0647 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f.", "BBT \u0628\u062e\u0634\u06cc \u0627\u0632 \u0628\u0631\u0646\u0627\u0645\u0647\u0654 \u0628\u0639\u062f\u06cc \u0628\u0631\u0627\u06cc \u062a\u062e\u0645\u06a9 \u0627\u0633\u062a \u0646\u0647 \u0642\u062f\u0645 \u0627\u0648\u0644.", "HSG \u062f\u0631 \u0645\u0631\u0627\u062d\u0644 \u0628\u0639\u062f\u06cc \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0644\u0648\u0644\u0647 \u0642\u0631\u0627\u0631 \u0645\u06cc\u200c\u06af\u06cc\u0631\u062f."],
  },
  (28, 99): {
   "topic": "thecaLuteinCyst",
   "lead": "\u06a9\u06cc\u0633\u062a \u062a\u062e\u0645\u062f\u0627\u0646 \u06f1\u06f0\u00d7\u06f1\u06f2 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631\u06cc \u062c\u062f\u0627\u0631 \u0646\u0627\u0632\u06a9 \u062d\u06cc\u0646 \u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0628\u0631\u0627\u06cc \u0645\u0648\u0644 \u06a9\u0627\u0645\u0644: \u06a9\u06cc\u0633\u062a \u062a\u06a9\u0627 \u0644\u0648\u062a\u0626\u06cc\u0646 \u062f\u0631 \u067e\u0627\u0633\u062e \u0628\u0647 BHCG \u0628\u0627\u0644\u0627 \u0648 \u0628\u0627 \u062a\u062e\u0644\u06cc\u0647\u0654 \u0645\u0648\u0644 \u062e\u0648\u062f\u0628\u0647\u200c\u062e\u0648\u062f \u067e\u0633 \u0645\u06cc\u200c\u0631\u0648\u062f \u0648 \u0627\u0642\u062f\u0627\u0645 \u062e\u0627\u0635\u06cc \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a \u0645\u06af\u0631 \u062a\u0648\u0631\u0634\u0646/\u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc.",
   "interpretation": "\u06a9\u06cc\u0633\u062a\u200c\u0647\u0627\u06cc \u062a\u06a9\u0627 \u0644\u0648\u062a\u0626\u06cc\u0646 \u0646\u0627\u0634\u06cc \u0627\u0632 \u062a\u062d\u0631\u06cc\u06a9 \u0634\u062f\u06cc\u062f \u062a\u062e\u0645\u062f\u0627\u0646 \u0628\u0647 \u0648\u0633\u06cc\u0644\u0647\u0654 BHCG \u0628\u0627\u0644\u0627\u06cc \u0645\u0648\u0644 \u0647\u0633\u062a\u0646\u062f \u0648 \u067e\u0633 \u0627\u0632 \u0628\u0631\u062f\u0627\u0634\u062a\u0646 \u0628\u0627\u0641\u062a \u0645\u0648\u0644 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u062f\u0631 \u0686\u0646\u062f \u0647\u0641\u062a\u0647 \u062a\u0627 \u0686\u0646\u062f \u0645\u0627\u0647 \u06a9\u0648\u0686\u06a9 \u0648 \u0645\u062d\u0648 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f\u061b \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u062d\u06cc\u0646 \u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc\u060c \u0627\u06af\u0631 \u062a\u0648\u0631\u0634\u0646 \u06cc\u0627 \u0646\u0634\u062a \u06cc\u0627 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0641\u0639\u0627\u0644 \u0646\u0628\u0627\u0634\u062f\u060c \u06a9\u06cc\u0633\u062a\u06a9\u062a\u0648\u0645\u06cc \u06cc\u0627 \u0627\u0648\u0641\u0648\u0631\u06a9\u062a\u0648\u0645\u06cc \u06cc\u0627 \u0622\u0633\u067e\u06cc\u0631\u0627\u0633\u06cc\u0648\u0646 \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a \u0648 \u0646\u06af\u0647\u200c\u062f\u0627\u0634\u062a\u0646 \u062a\u062e\u0645\u062f\u0627\u0646 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0627\u0633\u062a.",
   "reasons": ["\u06a9\u06cc\u0633\u062a\u06a9\u062a\u0648\u0645\u06cc \u062f\u0631 \u06a9\u06cc\u0633\u062a\u200c\u0647\u0627\u06cc \u0648\u0627\u06a9\u0646\u0634\u06cc \u0628\u0647 BHCG \u0645\u0648\u0644 \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a.", "\u0627\u0648\u0641\u0648\u0631\u06a9\u062a\u0648\u0645\u06cc \u0627\u0642\u062f\u0627\u0645 \u0628\u0633\u06cc\u0627\u0631 \u062a\u0647\u0627\u062c\u0645\u06cc \u0627\u0633\u062a \u0648 \u062a\u0648\u062c\u06cc\u0647 \u0646\u062f\u0627\u0631\u062f.", "\u0622\u0633\u067e\u06cc\u0631\u0627\u0633\u06cc\u0648\u0646 \u06a9\u06cc\u0633\u062a \u0646\u06cc\u0632 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0628\u06cc\u200c\u062f\u0644\u06cc\u0644 \u0627\u0633\u062a.", "\u0645\u062f\u06cc\u0631\u06cc\u062a \u0627\u0646\u062a\u0638\u0627\u0631\u06cc \u067e\u0633 \u0627\u0632-\u062a\u062e\u0644\u06cc\u0647\u0654 \u0645\u0648\u0644 \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 100): {
   "topic": "sfhBelowBiometry",
   "lead": "\u0627\u062e\u062a\u0644\u0627\u0641 \u0627\u0631\u062a\u0641\u0627\u0639 \u0631\u062d\u0645 \u0628\u0627 \u0633\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc (\u06f3\u06f6 \u0647\u0641\u062a\u0647\u0654 LMP \u0648\u0644\u06cc \u0627\u0631\u062a\u0641\u0627\u0639 \u0631\u062d\u0645 \u0645\u0639\u0627\u062f\u0644 \u06f3\u06f2 \u0647\u0641\u062a\u0647): \u0642\u062f\u0645 \u0628\u0639\u062f\u06cc \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0628\u06cc\u0648\u0645\u062a\u0631\u06cc \u0628\u0631\u0627\u06cc \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0631\u0634\u062f \u062c\u0646\u06cc\u0646.",
   "interpretation": "\u0627\u062e\u062a\u0644\u0627\u0641 \u0686\u0647\u0627\u0631 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631 \u06cc\u0627 \u0628\u06cc\u0634\u200c\u062a\u0631 \u0628\u06cc\u0646 \u0627\u0631\u062a\u0641\u0627\u0639 \u0631\u062d\u0645 \u0648 \u0633\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0647\u0634\u062f\u0627\u0631 \u0628\u0631\u0627\u06cc \u062e\u0637\u0627\u06cc \u062a\u0627\u0631\u06cc\u062e \u06cc\u0627 \u0645\u062d\u062f\u0648\u062f\u06cc\u062a \u0631\u0634\u062f \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u0627\u0633\u062a \u0648 \u0627\u0648\u0644\u06cc\u0646 \u0627\u0628\u0632\u0627\u0631 \u062a\u0642\u0648\u06cc\u062a\u06cc\u060c \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0628\u06cc\u0648\u0645\u062a\u0631\u06cc (\u0633\u0631/\u0628\u0637\u0646/\u0631\u0627\u0646) \u0628\u0631\u0627\u06cc \u0628\u0631\u0622\u0648\u0631\u062f \u0648\u0632\u0646 \u0648 \u0631\u0634\u062f \u0627\u0633\u062a\u061b \u062f\u0627\u067e\u0644\u0631 \u06a9\u0627\u0644\u0631 \u0634\u0631\u06cc\u0627\u0646 \u0646\u0627\u0641\u06cc \u0642\u062f\u0645 \u0628\u0639\u062f\u06cc \u062f\u0631 \u0635\u0648\u0631\u062a \u062a\u0623\u06cc\u06cc\u062f IUGR \u0627\u0633\u062a\u060c \u062a\u0633\u062a\u200c\u0647\u0627\u06cc \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0633\u0644\u0627\u0645\u062a \u0628\u0639\u062f\u0627\u064b \u0644\u0627\u0632\u0645\u200c\u0627\u0646\u062f \u0648 \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0631 \u06a9\u0627\u0645\u0644\u0627\u064b \u0645\u0634\u062e\u0635 \u0645\u0642\u062f\u0645 \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0628\u06cc\u0648\u0645\u062a\u0631\u06cc \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0627\u0648\u0644\u06cc\u0646 \u0627\u0642\u062f\u0627\u0645 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062f\u0627\u067e\u0644\u0631 \u0634\u0631\u06cc\u0627\u0646 \u0646\u0627\u0641\u06cc \u0628\u0639\u062f \u0627\u0632 \u0645\u0633\u062a\u0646\u062f\u0634\u062f\u0646 IUGR \u062f\u0631 \u0628\u06cc\u0648\u0645\u062a\u0631\u06cc \u0645\u06cc\u200c\u0622\u06cc\u062f.", "\u062a\u0633\u062a\u200c\u0647\u0627\u06cc \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0633\u0644\u0627\u0645\u062a \u0628\u0639\u062f \u0627\u0632 \u0645\u0634\u062e\u0635\u200c\u0634\u062f\u0646 \u0645\u0634\u06a9\u0644 \u0631\u0634\u062f \u062f\u0631 \u0646\u0638\u0631 \u06af\u0631\u0641\u062a\u0647 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f.", "\u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u06cc\u0634 \u0627\u0632 \u0631\u0648\u0634\u0646\u200c\u0634\u062f\u0646 \u0631\u0634\u062f \u062c\u0646\u06cc\u0646 \u062f\u0631 \u0627\u06cc\u0646 \u0646\u0642\u0637\u0647 \u062f\u0631\u0633\u062a \u0646\u06cc\u0633\u062a."],
  },
  (28, 101): {
   "topic": "asbPregCulture",
   "lead": "\u0628\u0627\u06a9\u062a\u0631\u06cc\u0648\u0631\u06cc \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0645\u062a \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0631 \u0627\u0633\u0627\u0633 \u0646\u0645\u0648\u0646\u0647\u0654 U/A \u0622\u0644\u0648\u062f\u0647: \u062f\u0631\u062e\u0648\u0627\u0633\u062a \u06a9\u0634\u062a \u0627\u062f\u0631\u0627\u0631 \u0628\u0631\u0627\u06cc \u062a\u0623\u06cc\u06cc\u062f \u0648 \u0633\u067e\u0633 \u062f\u0631\u0645\u0627\u0646 \u0628\u0631 \u0627\u0633\u0627\u0633 \u0622\u0646\u062a\u06cc\u200c\u0628\u06cc\u0648\u06af\u0631\u0627\u0645.",
   "interpretation": "\u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc\u060c \u0628\u0627\u06a9\u062a\u0631\u06cc\u0648\u0631\u06cc \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0645\u062a \u0628\u0627\u06cc\u062f \u0628\u0627 \u06a9\u0634\u062a \u0627\u062f\u0631\u0627\u0631 \u062a\u0639\u062f\u0627\u062f \u0642\u0627\u0628\u0644 \u0645\u0644\u0627\u062d\u0638\u0647 (\u2265\u06f1\u06f0\u06f0 \u0647\u0632\u0627\u0631 \u06a9\u0644\u0646\u06cc\u200c\u0633\u0627\u0632 \u062f\u0631 \u0645\u06cc\u0644\u06cc\u200c\u0644\u06cc\u062a\u0631) \u062a\u0623\u06cc\u06cc\u062f \u0634\u0648\u062f \u0648 \u062f\u0631\u0645\u0627\u0646 \u0628\u0631 \u0627\u0633\u0627\u0633 \u0622\u0646\u062a\u06cc\u200c\u0628\u06cc\u0648\u06af\u0631\u0627\u0645 \u0627\u0646\u062c\u0627\u0645 \u0634\u0648\u062f \u0632\u06cc\u0631\u0627 \u062e\u0637\u0631 \u067e\u06cc\u0644\u0648\u0646\u0641\u0631\u06cc\u062a \u0648 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 \u06a9\u0627\u0647\u0634 \u0645\u06cc\u200c\u06cc\u0627\u0628\u062f\u061b \u0634\u0631\u0648\u0639 \u062f\u0631\u0645\u0627\u0646 \u062a\u062c\u0631\u0628\u06cc \u0628\u062f\u0648\u0646 \u06a9\u0634\u062a \u0628\u0631 \u067e\u0627\u06cc\u0647\u0654 \u06cc\u06a9 \u0646\u0645\u0648\u0646\u0647\u0654 \u0622\u0644\u0648\u062f\u0647 \u062f\u0631\u0633\u062a \u0646\u06cc\u0633\u062a \u0648 \u062a\u06a9\u0631\u0627\u0631 \u0633\u0627\u062f\u0647\u0654 U/A \u06cc\u0627 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0637\u062d \u062a\u063a\u06cc\u06cc\u0631\u062f\u0647\u0646\u062f\u0647\u0654 \u062a\u0635\u0645\u06cc\u0645 \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u062a\u06a9\u0631\u0627\u0631 U/A \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u062a\u0623\u06cc\u06cc\u062f \u0639\u0641\u0648\u0646\u062a \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f.", "\u0634\u0631\u0648\u0639 \u0622\u0646\u062a\u06cc\u200c\u0628\u06cc\u0648\u062a\u06cc\u06a9 \u0628\u062f\u0648\u0646 \u06a9\u0634\u062a-\u0622\u0646\u062a\u06cc\u200c\u0628\u06cc\u0648\u06af\u0631\u0627\u0645 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u06cc\u06a9 \u0645\u0631\u062d\u0644\u0647 \u062f\u06cc\u0631 \u0627\u0633\u062a.", "\u06a9\u0634\u062a \u0627\u062f\u0631\u0627\u0631 \u0628\u0631\u0627\u06cc \u062a\u0623\u06cc\u06cc\u062f \u0648 \u0647\u062f\u0627\u06cc\u062a \u062f\u0631\u0645\u0627\u0646 \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u06a9\u0644\u06cc\u0647 \u0648 \u0645\u062c\u0627\u0631\u06cc \u062f\u0631 \u0628\u0627\u06a9\u062a\u0631\u06cc\u0648\u0631\u06cc \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0645\u062a \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0631\u0648\u062a\u06cc\u0646 \u0646\u06cc\u0633\u062a."],
  },
  (28, 102): {
   "topic": "posttermComplication",
   "lead": "\u0627\u0632 \u0639\u0648\u0627\u0631\u0636 \u06a9\u0644\u0627\u0633\u06cc\u06a9 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u0633 \u0627\u0632 \u062a\u0631\u0645: \u062f\u06cc\u0633\u062a\u0648\u0634\u06cc (\u0628\u0631 \u0627\u062b\u0631 \u0645\u0627\u06a9\u0631\u0648\u0632\u0648\u0645\u06cc) \u062f\u0631 \u0627\u06cc\u0646 \u0641\u0647\u0631\u0633\u062a \u0628\u0631\u06af \u0628\u0631\u0646\u062f\u0647 \u0627\u0633\u062a\u061b PROM/\u067e\u0631\u0648\u06cc\u0627/\u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0631\u0627\u0628\u0637\u0647\u0654 \u0645\u0633\u062a\u0642\u06cc\u0645\u200c\u062a\u0631\u06cc \u0628\u0627 \u067e\u0633 \u0627\u0632 \u062a\u0631\u0645 \u0646\u062f\u0627\u0631\u0646\u062f.",
   "interpretation": "\u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u0633 \u0627\u0632 \u06f4\u06f2 \u0647\u0641\u062a\u0647 \u0628\u0627 \u0627\u0641\u0632\u0627\u06cc\u0634 \u0645\u0627\u06a9\u0631\u0648\u0632\u0648\u0645\u06cc\u060c \u062f\u06cc\u0633\u0645\u0627\u062a\u0648\u0631\u06cc\u062a\u06cc\u060c \u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0648 \u062e\u0637\u0631 \u062f\u06cc\u0633\u062a\u0648\u0634\u06cc \u0645\u06a9\u0627\u0646\u06cc\u06a9\u06cc (\u0628\u0647\u200c\u062e\u0635\u0648\u0635 \u062f\u06cc\u0633\u062a\u0648\u0634\u06cc \u0634\u0627\u0646\u0647) \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a\u061b \u062c\u0641\u062a \u067e\u0631\u0648\u06cc\u0627 \u0648\u0636\u0639\u06cc\u062a \u0645\u0648\u0642\u0639\u06cc\u062a\u06cc \u0627\u0633\u062a \u0648 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0628\u06cc\u0634\u200c\u062a\u0631 \u0628\u0627 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062a\u0631\u0645-\u067e\u0627\u06cc\u06cc\u0646 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a \u0648 PROM \u062f\u0631 \u0647\u0631 \u0633\u0646\u06cc \u0631\u062e \u0645\u06cc\u200c\u062f\u0647\u062f \u0648 \u0627\u0632 \u0639\u0648\u0627\u0631\u0636 \u0627\u062e\u062a\u0635\u0627\u0635\u06cc \u067e\u0633 \u0627\u0632 \u062a\u0631\u0645 \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u062c\u0641\u062a \u067e\u0631\u0648\u06cc\u0627 \u0627\u0631\u062a\u0628\u0627\u0637 \u0645\u0633\u062a\u0642\u06cc\u0645 \u0628\u0627 \u067e\u0633 \u0627\u0632 \u062a\u0631\u0645 \u0646\u062f\u0627\u0631\u062f.", "\u062f\u06cc\u0633\u062a\u0648\u0634\u06cc (\u0645\u0627\u06a9\u0631\u0648\u0632\u0648\u0645\u06cc) \u0627\u0632 \u0639\u0648\u0627\u0631\u0636 \u067e\u0633 \u0627\u0632 \u062a\u0631\u0645 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0627\u0631\u062a\u0628\u0627\u0637 \u0645\u0633\u062a\u0642\u06cc\u0645\u06cc \u0628\u0627 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u0633 \u0627\u0632 \u062a\u0631\u0645 \u0646\u062f\u0627\u0631\u062f.", "\u067e\u0627\u0631\u06af\u06cc \u0632\u0648\u062f\u0631\u0633 \u067e\u0631\u062f\u0647 \u062f\u0631 \u0647\u0631 \u0633\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0631\u062e \u0645\u06cc\u200c\u062f\u0647\u062f \u0648 \u0627\u062e\u062a\u0635\u0627\u0635\u06cc \u0628\u0647 \u067e\u0633 \u0627\u0632 \u062a\u0631\u0645 \u0646\u06cc\u0633\u062a."],
  },
  (28, 103): {
   "topic": "radiationDoseCompare",
   "lead": "\u062f\u0631 \u0627\u06cc\u0646 \u0641\u0647\u0631\u0633\u062a\u060c \u0633\u06cc\u200c\u062a\u06cc\u200c\u0627\u0633\u06a9\u0646 \u0634\u06a9\u0645 \u0628\u0627\u0644\u0627\u062a\u0631\u06cc\u0646 \u062f\u0648\u0632 \u062a\u0634\u0639\u0634\u0639\u06cc \u0628\u0631\u0627\u06cc \u062c\u0646\u06cc\u0646 \u0631\u0627 \u062f\u0627\u0631\u062f.",
   "interpretation": "\u062f\u0648\u0632\u0647\u0627\u06cc \u062a\u0642\u0631\u06cc\u0628\u06cc \u0628\u0647 \u062c\u0646\u06cc\u0646: \u0631\u0627\u062f\u06cc\u0648\u06af\u0631\u0627\u0641\u06cc \u062f\u0646\u062f\u0627\u0646 \u0648 \u0642\u0641\u0633\u0647\u0654 \u0633\u06cc\u0646\u0647 \u0628\u0633\u06cc\u0627\u0631 \u06a9\u0645 (\u06a9\u0645\u062a\u0631 \u0627\u0632 \u06f0\u066b\u06f0\u06f1 \u06af\u0631\u06cc)\u060c \u0645\u0627\u0645\u0648\u06af\u0631\u0627\u0641\u06cc \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u0645\u062d\u062f\u0648\u062f\u0628\u0648\u062f\u0646 \u0645\u06cc\u062f\u0627\u0646 \u0628\u0647 \u0633\u06cc\u0646\u0647 \u06a9\u0645 \u0627\u0633\u062a \u0648\u0644\u06cc \u062f\u0648\u0632 \u0622\u0646 \u0628\u06cc\u0634\u062a\u0631 \u0627\u0632 \u0631\u0627\u062f\u06cc\u0648\u06af\u0631\u0627\u0641\u06cc \u062f\u0646\u062f\u0627\u0646 \u0648 \u0642\u0641\u0633\u0647\u0654 \u0633\u06cc\u0646\u0647 \u0627\u0633\u062a \u0648 \u0633\u06cc\u200c\u062a\u06cc\u200c\u0627\u0633\u06a9\u0646 \u0634\u06a9\u0645 \u0648 \u0644\u06af\u0646 \u062f\u0631 \u0645\u062d\u062f\u0648\u062f\u0647\u0654 \u0686\u0646\u062f \u0635\u062f\u0645 \u062a\u0627 \u0686\u0646\u062f \u062f\u0647\u0645 \u06af\u06cc \u0627\u0633\u062a \u0648 \u0628\u0633\u06cc\u0627\u0631 \u0628\u0627\u0644\u0627\u062a\u0631 \u0627\u0633\u062a\u061b \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u062f\u0631 \u0633\u0624\u0627\u0644\u0627\u062a \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0628\u0627\u0632\u062f\u0647\u06cc \u062a\u0634\u0639\u0634\u0639\u06cc \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0633\u06cc\u200c\u062a\u06cc\u200c\u0627\u0633\u06a9\u0646 \u0634\u06a9\u0645\u06cc \u0628\u0627\u0644\u0627\u062a\u0631\u06cc\u0646 \u0627\u0633\u062a.",
   "reasons": ["\u0633\u06cc\u200c\u062a\u06cc\u200c\u0627\u0633\u06a9\u0646 \u0634\u06a9\u0645 \u0628\u06cc\u0634\u200c\u062a\u0631\u06cc\u0646 \u062f\u0648\u0632 \u0631\u0627 \u062f\u0627\u0631\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0631\u0627\u062f\u06cc\u0648\u06af\u0631\u0627\u0641\u06cc \u062f\u0646\u062f\u0627\u0646 \u062f\u0648\u0632 \u062a\u0634\u0639\u0634\u0639\u06cc \u0628\u0633\u06cc\u0627\u0631 \u06a9\u0645\u06cc \u0628\u0647 \u062c\u0646\u06cc\u0646 \u0645\u06cc\u200c\u0631\u0633\u0627\u0646\u062f.", "\u0639\u06a9\u0633 \u0642\u0641\u0633\u0647\u0654 \u0633\u06cc\u0646\u0647 \u062f\u0648\u0632 \u06a9\u0645\u06cc \u0628\u0647 \u062c\u0646\u06cc\u0646 \u0645\u06cc\u200c\u0631\u0633\u0627\u0646\u062f.", "\u0645\u0627\u0645\u0648\u06af\u0631\u0627\u0641\u06cc \u0646\u0632\u062f\u06cc\u06a9\u200c\u062a\u0631 \u0628\u0647 \u0633\u06cc\u0646\u0647 \u0627\u0633\u062a \u0648 \u0627\u0632 \u0633\u06cc\u200c\u062a\u06cc \u0634\u06a9\u0645 \u06a9\u0645\u062a\u0631 \u0627\u0633\u062a."],
  },
  (28, 104): {
   "topic": "severePreeclampsiaFeatures",
   "lead": "\u0627\u0632 \u0645\u06cc\u0627\u0646 \u0634\u0627\u062e\u0635\u200c\u0647\u0627\u06cc \u0627\u06cc\u0646 \u0628\u06cc\u0645\u0627\u0631\u060c \u062a\u0646\u0647\u0627 \u00ab\u0633\u0637\u062d \u067e\u0644\u0627\u06a9\u062a \u06f9\u06f0 \u0647\u0632\u0627\u0631\u00bb \u062f\u0631 \u0641\u0647\u0631\u0633\u062a \u0645\u0639\u06cc\u0627\u0631\u0647\u0627\u06cc \u0639\u0644\u0627\u06cc\u0645 \u0634\u062f\u06cc\u062f \u0642\u0631\u0627\u0631 \u0645\u06cc\u200c\u06af\u06cc\u0631\u062f (\u0641\u0634\u0627\u0631 \u06f1\u06f5\u06f0/\u06f1\u06f0\u06f0 \u0634\u062f\u06cc\u062f \u0646\u06cc\u0633\u062a\u060c \u067e\u0631\u0648\u062a\u0626\u06cc\u0646\u0648\u0631\u06cc \u062f\u06cc\u06af\u0631 \u0645\u0644\u0627\u06a9 \u0634\u062f\u062a \u0646\u06cc\u0633\u062a \u0648 \u062f\u0631\u062f \u0627\u067e\u06cc\u200c\u06af\u0627\u0633\u062a\u0631 \u067e\u0627\u06cc\u062f\u0627\u0631 \u0648 \u067e\u0627\u0633\u062e\u200c\u062f\u0647\u0646\u062f\u0647 \u0628\u0647 \u0622\u0646\u062a\u06cc\u200c\u0627\u0633\u06cc\u062f \u062e\u0641\u06cc\u0641\u200c\u062a\u0631 \u0631\u062a\u0628\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f).",
   "interpretation": "\u0631\u0627\u0647\u0646\u0645\u0627\u06cc \u062c\u062f\u06cc\u062f \u062a\u0634\u062f\u06cc\u062f \u0645\u0639\u06cc\u0627\u0631\u0647\u0627\u06cc \u0634\u062f\u062a \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0631\u0627 \u0633\u0627\u062f\u0647 \u06a9\u0631\u062f\u0647 \u0627\u0633\u062a: \u0641\u0634\u0627\u0631 \u0628\u0627\u0644\u0627\u06cc \u06cc\u0627 \u0645\u0633\u0627\u0648\u06cc \u06f1\u06f6\u06f0/\u06f1\u06f1\u06f0\u060c \u062a\u0631\u0648\u0645\u0628\u0648\u0633\u06cc\u062a\u0648\u067e\u0646\u06cc \u06a9\u0645\u062a\u0631 \u0627\u0632 \u06f1\u06f0\u06f0\u066c\u06f0\u06f0\u06f0\u060c \u0627\u0641\u0632\u0627\u06cc\u0634 \u06a9\u0631\u0627\u062a\u06cc\u0646\u06cc\u0646\u060c \u0627\u062e\u062a\u0644\u0627\u0644 \u0639\u0645\u0644\u06a9\u0631\u062f \u06a9\u0628\u062f \u0628\u0627 \u062f\u0631\u062f \u0648 \u062a\u0633\u062a\u200c\u0647\u0627\u06cc \u0628\u0627\u0644\u0627\u060c \u0639\u0644\u0627\u06cc\u0645 \u0639\u0635\u0628\u06cc/\u0631\u06cc\u0648\u06cc\u061b \u067e\u0631\u0648\u062a\u0626\u06cc\u0646\u0648\u0631\u06cc \u0648 \u0627\u062f\u0645 \u062f\u06cc\u06af\u0631 \u062c\u0632\u0621 \u0645\u0639\u06cc\u0627\u0631 \u0634\u062f\u062a \u0646\u06cc\u0633\u062a\u0646\u062f \u0648 \u0641\u0634\u0627\u0631 \u0622\u0646 \u0628\u06cc\u0645\u0627\u0631 \u062f\u0631 \u0627\u06cc\u0646\u200c\u062c\u0627 \u0634\u062f\u06cc\u062f \u0646\u06cc\u0633\u062a \u0648 \u062f\u0631\u062f \u0627\u067e\u06cc\u200c\u06af\u0627\u0633\u062a\u0631 \u067e\u0627\u0633\u062e\u200c\u062f\u0647\u0646\u062f\u0647 \u0628\u0647 \u0622\u0646\u062a\u06cc\u200c\u0627\u0633\u06cc\u062f \u06a9\u0645\u062a\u0631 \u0627\u0632 \u0645\u0639\u06cc\u0627\u0631\u0647\u0627\u06cc \u0622\u0632\u0645\u0627\u06cc\u0634\u06af\u0627\u0647\u06cc \u0645\u0639\u0646\u0627\u0634\u0646\u0627\u062e\u062a\u06cc \u0627\u0633\u062a\u061b \u062f\u0631 \u0645\u06cc\u0627\u0646 \u06af\u0632\u06cc\u0646\u0647\u200c\u0647\u0627 \u067e\u0644\u0627\u06a9\u062a \u06a9\u0645\u062a\u0631 \u0627\u0632 \u06f1\u06f0\u06f0\u066c\u06f0\u06f0\u06f0 \u062a\u0646\u0647\u0627 \u0634\u0627\u062e\u0635 \u0634\u062f\u062a\u06cc \u0627\u0633\u062a \u06a9\u0647 \u0648\u062c\u0648\u062f \u062f\u0627\u0631\u062f.",
   "reasons": ["\u0641\u0634\u0627\u0631 \u06f1\u06f5\u06f0/\u06f1\u06f0\u06f0 \u062f\u0631 \u0622\u0633\u062a\u0627\u0646\u0647\u0654 \u067e\u0631\u0641\u0634\u0627\u0631\u06cc \u0634\u062f\u06cc\u062f \u0646\u06cc\u0633\u062a.", "\u067e\u0644\u0627\u06a9\u062a ~\u06f9\u06f0\u066c\u06f0\u06f0\u06f0 \u062c\u0632\u0621 \u0645\u0639\u06cc\u0627\u0631 \u0634\u062f\u06cc\u062f \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062f\u0631\u062f \u0627\u067e\u06cc\u200c\u06af\u0627\u0633\u062a\u0631 \u067e\u0627\u06cc\u062f\u0627\u0631 \u0648 \u067e\u0627\u0633\u062e\u200c\u062f\u0647\u0646\u062f\u0647 \u0628\u0647 \u0622\u0646\u062a\u06cc\u200c\u0627\u0633\u06cc\u062f \u0628\u0647\u200c\u062e\u0648\u062f\u06cc\u200c\u062e\u0648\u062f \u0645\u0639\u06cc\u0627\u0631 \u0634\u062f\u062a \u0646\u06cc\u0633\u062a.", "\u067e\u0631\u0648\u062a\u0626\u06cc\u0646\u0648\u0631\u06cc \u062f\u06cc\u06af\u0631 \u062f\u0631 \u062a\u0639\u0631\u06cc\u0641 \u0634\u062f\u062a \u0642\u0631\u0627\u0631 \u0646\u0645\u06cc\u200c\u06af\u06cc\u0631\u062f."],
  },
  (28, 105): {
   "topic": "hypothyroidPregRisk",
   "lead": "\u0627\u0632 \u0639\u0648\u0627\u0631\u0636 \u0645\u0631\u062a\u0628\u0637 \u0628\u0627 \u0647\u06cc\u067e\u0648\u062a\u06cc\u0631\u0648\u0626\u06cc\u062f\u06cc \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc\u060c \u0627\u0641\u0632\u0627\u06cc\u0634 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 (\u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u0622\u062a\u0648\u0646\u06cc \u0631\u062d\u0645\u06cc \u0645\u0631\u062a\u0628\u0637) \u0628\u06cc\u0634\u200c\u062a\u0631\u06cc\u0646 \u0647\u0645\u200c\u067e\u0648\u0634\u0627\u0646\u06cc \u0631\u0627 \u062f\u0627\u0631\u062f.",
   "interpretation": "\u0647\u06cc\u067e\u0648\u062a\u06cc\u0631\u0648\u0626\u06cc\u062f\u06cc \u062f\u0631\u0645\u0627\u0646\u200c\u0646\u0634\u062f\u0647 \u0628\u0627 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc\u060c \u0627\u0641\u062a \u0641\u0634\u0627\u0631\u060c \u06a9\u0645\u200c\u062e\u0648\u0646\u06cc\u060c \u0622\u062a\u0648\u0646\u06cc \u0631\u062d\u0645\u06cc \u0648 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0648 \u062d\u062a\u06cc \u0633\u0642\u0637 \u0648 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a\u061b \u0645\u0627\u06a9\u0631\u0648\u0632\u0648\u0645\u06cc \u062f\u0631 \u062f\u06cc\u0627\u0628\u062a\u060c \u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 \u062f\u0631 \u0639\u0641\u0648\u0646\u062a \u0627\u062f\u0631\u0627\u0631\u06cc \u0648 \u067e\u0627\u0631\u06af\u06cc \u0632\u0648\u062f\u0631\u0633 \u067e\u0631\u062f\u0647\u200c\u0647\u0627 \u0627\u0631\u062a\u0628\u0627\u0637 \u0645\u0633\u062a\u0642\u06cc\u0645\u200c\u062a\u0631\u06cc \u0628\u0627 \u0647\u06cc\u067e\u0648\u062a\u06cc\u0631\u0648\u0626\u06cc\u062f\u06cc \u0646\u062f\u0627\u0631\u0646\u062f \u0648 \u062f\u0631 \u0628\u06cc\u0646 \u0627\u06cc\u0646 \u06af\u0632\u06cc\u0646\u0647\u200c\u0647\u0627 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0647\u0645\u0631\u0627\u0647 \u0622\u062a\u0648\u0646\u06cc \u0628\u0647\u062a\u0631\u06cc\u0646 \u067e\u0627\u0633\u062e \u0627\u0633\u062a.",
   "reasons": ["\u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0628\u0627 \u0647\u06cc\u067e\u0648\u062a\u06cc\u0631\u0648\u0626\u06cc\u062f\u06cc \u0645\u0631\u062a\u0628\u0637 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0645\u0627\u06a9\u0631\u0648\u0632\u0648\u0645\u06cc \u0628\u0627 \u0647\u06cc\u067e\u0648\u062a\u06cc\u0631\u0648\u0626\u06cc\u062f\u06cc \u0627\u0631\u062a\u0628\u0627\u0637 \u0645\u0633\u062a\u0642\u06cc\u0645\u06cc \u0646\u062f\u0627\u0631\u062f.", "\u0639\u0641\u0648\u0646\u062a \u0627\u062f\u0631\u0627\u0631\u06cc \u0627\u0631\u062a\u0628\u0627\u0637 \u0645\u0633\u062a\u0642\u06cc\u0645\u06cc \u0628\u0627 \u062a\u06cc\u0631\u0648\u0626\u06cc\u062f \u0646\u062f\u0627\u0631\u062f.", "\u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 \u0628\u0627\u0644\u0642\u0648\u0647 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a \u0648\u0644\u06cc \u06af\u0632\u06cc\u0646\u0647\u0654 \u0627\u06cc\u0646 \u06a9\u0644\u06cc\u062f \u0627\u0633\u062a \u0646\u0647 \u0622\u0646."],
  },
  (28, 106): {
   "topic": "papIntervalNegative",
   "lead": "\u0632\u0646 \u06f3\u06f2 \u0633\u0627\u0644\u0647 \u0628\u0627 \u0633\u06cc\u062a\u0648\u0644\u0648\u0698\u06cc \u0645\u0646\u0641\u06cc \u0648 \u062a\u0633\u062a HPV \u0645\u0646\u0641\u06cc: \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0645\u062c\u062f\u062f \u0646\u0628\u0627\u06cc\u062f \u0628\u0627 \u0641\u0627\u0635\u0644\u0647\u0654 \u06a9\u0648\u062a\u0627\u0647\u200c\u062a\u0631 \u0627\u0632 \u06f3 \u0633\u0627\u0644 \u0627\u0646\u062c\u0627\u0645 \u0634\u0648\u062f.",
   "interpretation": "\u0648\u0642\u062a\u06cc \u0647\u0631 \u062f\u0648 \u062a\u0633\u062a \u0633\u06cc\u062a\u0648\u0644\u0648\u0698\u06cc \u0648 \u062a\u0633\u062a HPV \u0645\u0646\u0641\u06cc \u06af\u0632\u0627\u0631\u0634 \u0645\u06cc\u200c\u0634\u0648\u062f \u062e\u0637\u0631 \u0628\u0633\u06cc\u0627\u0631 \u067e\u0627\u06cc\u06cc\u0646 \u0645\u06cc\u200c\u0631\u0648\u062f \u0648 \u067e\u0631\u0648\u062a\u06a9\u0644 \u0645\u062a\u0639\u0627\u0631\u0641 \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u06a9\u0646\u062f \u06a9\u0647 \u0628\u0627\u0632\u0647\u0654 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0631\u0627 \u0628\u0647 \u0647\u0631 \u06f3-\u06f5 \u0633\u0627\u0644 \u0628\u0631\u0633\u0627\u0646\u0646\u062f (\u062f\u0631 \u0641\u0647\u0631\u0633\u062a \u062f\u0627\u062e\u0644\u06cc \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0628\u0647 \u06f3 \u0633\u0627\u0644 \u0627\u0634\u0627\u0631\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f) \u0648 \u0627\u06cc\u0646 \u067e\u0631\u0633\u0634 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u062f \u06a9\u0647 \u0636\u0631\u0648\u0631\u062a\u06cc \u0628\u0631\u0627\u06cc \u062a\u06a9\u0631\u0627\u0631 \u0633\u0627\u0644\u0627\u0646\u0647\u060c \u0686\u0647 \u0628\u0627 \u0633\u06cc\u062a\u0648\u0644\u0648\u0698\u06cc \u062a\u0646\u0647\u0627 \u06cc\u0627 \u0628\u0627 co-test \u0648\u062c\u0648\u062f \u0646\u062f\u0627\u0631\u062f\u061b \u062a\u06a9\u0631\u0627\u0631 \u0633\u0627\u0644\u0627\u0646\u0647 \u0628\u0627 HPV \u06cc\u0627 co-test \u062f\u0631 \u0686\u0646\u06cc\u0646 \u0648\u0636\u0639\u06cc \u0632\u06cc\u0627\u062f\u0647\u200c\u0631\u0648\u06cc \u0627\u0633\u062a.",
   "reasons": ["\u0641\u0627\u0635\u0644\u0647\u0654 \u0646\u0632\u062f\u06cc\u06a9\u200c\u062a\u0631 \u0627\u0632 \u06f3 \u0633\u0627\u0644 \u0628\u0631\u0627\u06cc \u0627\u06cc\u0646 \u0632\u0646 \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062a\u0633\u062a HPV \u0633\u0627\u0644\u0627\u0646\u0647 \u062f\u0631 \u0646\u062a\u06cc\u062c\u0647 \u0645\u0646\u0641\u06cc \u06cc\u06a9 co-test \u0642\u0628\u0644\u06cc \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a.", "\u0633\u06cc\u062a\u0648\u0644\u0648\u0698\u06cc \u0633\u0627\u0644\u0627\u0646\u0647 \u0628\u0631\u0627\u06cc \u0628\u06cc\u0645\u0627\u0631 \u0628\u0627 co-test \u0645\u0646\u0641\u06cc \u0627\u0641\u0631\u0627\u0637 \u0627\u0633\u062a.", "co-test \u0633\u0627\u0644\u0627\u0646\u0647 \u062f\u0631 \u0686\u0646\u06cc\u0646 \u0628\u06cc\u0645\u0627\u0631\u06cc \u0627\u0641\u0631\u0627\u0637 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0627\u0633\u062a."],
  },
  (28, 107): {
   "topic": "iudInsertionTiming",
   "lead": "\u0628\u0647\u062a\u0631\u06cc\u0646 \u0632\u0645\u0627\u0646 \u06af\u0630\u0627\u0634\u062a\u0646 IUD \u062f\u0631 \u062d\u0627\u0644 \u062d\u0627\u0636\u0631 \u0642\u0627\u0639\u062f\u06af\u06cc \u0627\u0633\u062a \u0686\u0648\u0646 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u06a9\u0645\u06cc \u0628\u0627\u0632\u062a\u0631 \u0627\u0633\u062a \u0648 \u063a\u06cc\u0631\u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062a\u0623\u06cc\u06cc\u062f \u0622\u0645\u0627\u062f\u0647\u200c\u062a\u0631 \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "interpretation": "\u062f\u0631 \u062f\u0648\u0631\u0627\u0646 \u0642\u0627\u0639\u062f\u06af\u06cc\u060c \u0633\u0631\u0648\u06cc\u06a9\u0633 \u06a9\u0645\u06cc \u0628\u0627\u0632\u062a\u0631 \u0627\u0633\u062a \u0648 \u06a9\u0627\u0631 \u062f\u0631\u062c \u0622\u0633\u0627\u0646\u200c\u062a\u0631 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0639\u062f\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0627 \u0645\u0646\u0637\u0642 \u0632\u0645\u0627\u0646\u06cc \u0642\u0648\u06cc\u200c\u062a\u0631 \u0627\u0633\u062a\u061b \u06af\u0630\u0627\u0634\u062a\u0646 IUD \u062f\u0631 \u0632\u0645\u0627\u0646 \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u06cc\u0627 \u0641\u0627\u0632 \u0644\u0648\u062a\u0626\u0627\u0644 \u0628\u0647\u200c\u0627\u062d\u062a\u0645\u0627\u0644 \u0632\u06cc\u0627\u062f \u062e\u0637\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc/\u0633\u0642\u0637 \u0631\u0627 \u0627\u0641\u0632\u0627\u06cc\u0634 \u0645\u06cc\u200c\u062f\u0647\u062f \u0648 \u00ab\u0628\u0644\u0627\u0641\u0627\u0635\u0644\u0647 \u067e\u0633 \u0627\u0632 \u067e\u0627\u06a9\u200c\u0634\u062f\u0646\u00bb \u0646\u0633\u0628\u062a \u0628\u0647 \u062d\u06cc\u0646 \u0645\u0646\u0633 \u0627\u062d\u062a\u0645\u0627\u0644 \u06a9\u0645\u062a\u0631\u06cc \u062f\u0627\u0631\u062f.",
   "reasons": ["\u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u0628\u0631\u0627\u06cc \u06af\u0630\u0627\u0634\u062a\u0646 IUD \u0632\u0645\u0627\u0646 \u0645\u0646\u0627\u0633\u0628\u06cc \u0646\u06cc\u0633\u062a.", "\u062d\u06cc\u0646 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0642\u0627\u0639\u062f\u06af\u06cc \u0628\u0647\u062a\u0631\u06cc\u0646 \u0632\u0645\u0627\u0646 \u06af\u0630\u0627\u0634\u062a\u0646 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u067e\u0627\u06a9\u200c\u0634\u062f\u0646 \u067e\u0633 \u0627\u0632 \u0642\u0627\u0639\u062f\u06af\u06cc \u0627\u062d\u062a\u0645\u0627\u0644 \u06a9\u0645\u062a\u0631\u06cc \u0646\u0633\u0628\u062a \u0628\u0647 \u062d\u06cc\u0646 \u0645\u0646\u0633 \u062f\u0627\u0631\u062f.", "\u0641\u0627\u0632 \u0644\u0648\u062a\u0626\u0627\u0644 \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u0627\u062d\u062a\u0645\u0627\u0644 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0632\u0645\u0627\u0646 \u0645\u0646\u0627\u0633\u0628 \u062f\u0631\u062c IUD \u0646\u06cc\u0633\u062a."],
  },
  (28, 108): {
   "topic": "pmbEndometrialBiopsy",
   "lead": "\u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632 \u06cc\u0627\u0626\u0633\u06af\u06cc + \u0636\u062e\u0627\u0645\u062a \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u06f6 \u0645\u06cc\u0644\u06cc\u200c\u0645\u062a\u0631 (\u0628\u0627\u0644\u0627\u062a\u0631 \u0627\u0632 \u0622\u0633\u062a\u0627\u0646\u0647\u0654 \u06f4-\u06f5 \u0645\u06cc\u0644\u06cc\u200c\u0645\u062a\u0631): \u0628\u06cc\u0648\u067e\u0633\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0644\u0627\u0632\u0645 \u0627\u0633\u062a \u0642\u0628\u0644 \u0627\u0632 \u0647\u0631 \u062f\u0631\u0645\u0627\u0646 \u0647\u0648\u0631\u0645\u0648\u0646\u06cc.",
   "interpretation": "\u062f\u0631 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632 \u06cc\u0627\u0626\u0633\u06af\u06cc\u060c \u0622\u0633\u062a\u0627\u0646\u0647\u0654 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc\u06a9 \u0636\u062e\u0627\u0645\u062a \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u062d\u062f\u0648\u062f \u06f4-\u06f5 \u0645\u06cc\u0644\u06cc\u200c\u0645\u062a\u0631 \u0627\u0633\u062a\u061b \u0636\u062e\u0627\u0645\u062a \u06f6 \u0645\u06cc\u0644\u06cc\u200c\u0645\u062a\u0631 \u062f\u0631 \u0628\u0627\u0644\u06cc\u0646 \u0645\u0639\u0646\u0627\u062f\u0627\u0631 \u0642\u0631\u0627\u0631 \u0645\u06cc\u200c\u06af\u06cc\u0631\u062f \u0648 \u0628\u0627\u06cc\u062f \u0628\u0627 \u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 (\u0646\u0647 \u062a\u062c\u0648\u06cc\u0632 \u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646/\u0627\u0633\u062a\u0631\u0648\u0698\u0646/OCP \u0628\u062f\u0648\u0646 \u062a\u0634\u062e\u06cc\u0635) \u067e\u0627\u062a\u0648\u0644\u0648\u0698\u06cc \u0631\u0648\u0634\u0646 \u0634\u0648\u062f \u0686\u0648\u0646 \u062a\u062c\u0648\u06cc\u0632 \u0647\u0648\u0631\u0645\u0648\u0646 \u0628\u062f\u0648\u0646 \u0631\u062f \u0628\u062f\u062e\u06cc\u0645\u06cc/\u0647\u0627\u06cc\u067e\u0631\u067e\u0644\u0627\u0632\u06cc \u063a\u0644\u0637 \u0627\u0633\u062a.",
   "reasons": ["\u062a\u062c\u0648\u06cc\u0632 \u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u067e\u06cc\u0634 \u0627\u0632 \u0631\u0648\u0634\u0646\u200c\u0634\u062f\u0646 \u067e\u0627\u062a\u0648\u0644\u0648\u0698\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u062f\u0631\u0633\u062a \u0646\u06cc\u0633\u062a.", "\u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u062e\u0648\u0631\u0627\u06a9\u06cc \u062f\u0631 PMB \u0628\u062f\u0648\u0646 \u062a\u0634\u062e\u06cc\u0635 \u0645\u0645\u0646\u0648\u0639 \u0645\u0646\u0637\u0642\u06cc \u0627\u0633\u062a.", "\u0642\u0631\u0635 \u062a\u0631\u06a9\u06cc\u0628\u06cc \u0636\u062f\u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0631 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632 \u06cc\u0627\u0626\u0633\u06af\u06cc \u062c\u0627\u06cc\u06af\u0627\u0647\u06cc \u0646\u062f\u0627\u0631\u062f.", "\u0628\u06cc\u0648\u067e\u0633\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u062f\u0631 ET=\u06f6 \u0645\u06cc\u0644\u06cc\u200c\u0645\u062a\u0631 \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 109): {
   "topic": "twinSingleDeathDc",
   "lead": "\u0641\u0648\u062a \u06cc\u06a9 \u062c\u0646\u06cc\u0646 \u062f\u0631 \u062f\u0648\u0642\u0644\u0648\u06cc\u06cc \u062f\u06cc\u200c\u06a9\u0648\u0631\u06cc\u0648\u0646 \u062f\u0631 \u06f3\u06f5 \u0647\u0641\u062a\u0647: \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0642\u0644 \u0632\u0646\u062f\u0647 \u062a\u0627 \u0646\u0632\u062f\u06cc\u06a9\u200c\u062a\u0631\u06cc\u0646 \u0632\u0645\u0627\u0646 \u0645\u0637\u0645\u0626\u0646 (\u062a\u0631\u0645 \u0645\u0637\u0627\u0628\u0642 \u067e\u0631\u0648\u062a\u06a9\u0644) \u0627\u062f\u0627\u0645\u0647 \u0645\u06cc\u200c\u06cc\u0627\u0628\u062f \u0648 \u0633\u0632\u0627\u0631\u06cc\u0646/\u0627\u0644\u0642\u0627 \u0641\u0648\u0631\u06cc \u0641\u0642\u0637 \u0628\u0631 \u0627\u0633\u0627\u0633 \u0639\u0644\u062a \u062f\u06cc\u06af\u0631 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "interpretation": "\u062f\u0631 \u062f\u0648\u0642\u0644\u0648\u06cc\u06cc \u062f\u06cc\u200c\u06a9\u0648\u0631\u06cc\u0648\u0646 \u0641\u0648\u062a \u06cc\u06a9 \u062c\u0646\u06cc\u0646 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u0646\u0628\u0648\u062f \u062a\u062f\u0627\u062e\u0644 \u06af\u0631\u062f\u0634\u06cc\u060c \u0627\u062b\u0631 \u0645\u0633\u062a\u0642\u06cc\u0645 \u0631\u0648\u06cc \u0642\u0644 \u062f\u06cc\u06af\u0631 \u0646\u062f\u0627\u0631\u062f \u0648 \u0645\u062f\u06cc\u0631\u06cc\u062a \u0627\u0646\u062a\u0638\u0627\u0631\u06cc \u0628\u0627 \u067e\u0627\u06cc\u0634 \u0642\u0644 \u0632\u0646\u062f\u0647 \u0648 \u0645\u0627\u062f\u0631 (\u0648 \u0641\u06cc\u0628\u0631\u06cc\u0646\u0648\u0698\u0646 \u0645\u0627\u062f\u0631 \u062f\u0631 \u0647\u0641\u062a\u0647\u200c\u0647\u0627) \u0645\u0646\u0627\u0633\u0628 \u0627\u0633\u062a\u061b \u06a9\u0648\u0631\u062a\u06cc\u06a9\u0648\u0627\u0633\u062a\u0631\u0648\u0626\u06cc\u062f \u0648 \u062e\u062a\u0645 \u0641\u0648\u0631\u06cc \u06cc\u0627 \u0633\u0632\u0627\u0631\u06cc\u0646 \u0627\u0648\u0631\u0698\u0627\u0646\u0633 \u0635\u0631\u0641\u0627\u064b \u0628\u0647\u200c\u0637\u0648\u0631 \u0631\u0648\u062a\u06cc\u0646 \u067e\u0633 \u0627\u0632 \u0641\u0648\u062a \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u06cc\u06a9 \u0642\u0644 \u062f\u0631 \u0641\u0631\u0645 \u062f\u06cc\u200c\u06a9\u0648\u0631\u06cc\u0648\u0646 \u062a\u0648\u0635\u06cc\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0627\u062f\u0627\u0645\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0632\u06cc\u0631 \u0646\u0638\u0631 \u062f\u0631 \u0627\u06cc\u0646\u06af\u0648\u0646\u0647 \u0645\u0648\u0627\u0631\u062f \u0645\u0646\u0637\u0642\u06cc \u0627\u0633\u062a.",
   "reasons": ["\u06a9\u0648\u0631\u062a\u0648\u0646 \u0648 \u062e\u062a\u0645 \u0641\u0648\u0631\u06cc \u0628\u062f\u0648\u0646 \u0639\u0644\u062a \u0627\u0636\u0627\u0641\u06cc \u062f\u0631\u0633\u062a \u0646\u06cc\u0633\u062a.", "\u0633\u0632\u0627\u0631\u06cc\u0646 \u0627\u0648\u0631\u0698\u0627\u0646\u0633 \u0641\u0642\u0637 \u0628\u0631\u0627\u06cc \u0639\u0644\u062a \u0632\u0627\u06cc\u0645\u0627\u0646\u06cc \u062f\u06cc\u06af\u0631 \u0627\u0633\u062a.", "\u062a\u062d\u0631\u06cc\u06a9 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0628\u062f\u0648\u0646 \u0639\u0644\u062a \u062f\u0631 \u0627\u06cc\u0646 \u0648\u0636\u0639\u06cc\u062a \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a.", "\u0627\u062f\u0627\u0645\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0627 \u067e\u0627\u06cc\u0634 \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 110): {
   "topic": "nuchalCordManagement",
   "lead": "\u0628\u0646\u062f \u0646\u0627\u0641 \u062f\u0648\u0631 \u06af\u0631\u062f\u0646 (nuchal cord) \u062f\u0631 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u06f3\u06f6 \u0647\u0641\u062a\u0647 \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u0639\u0644\u062a\u06cc \u0628\u0631\u0627\u06cc \u0633\u0632\u0627\u0631\u06cc\u0646 \u0646\u06cc\u0633\u062a \u0648 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0633\u06cc\u0631 \u0637\u0628\u06cc\u0639\u06cc \u062e\u0648\u062f \u0631\u0627 \u062a\u0627 \u062a\u0634\u062e\u06cc\u0635 \u0627\u062d\u062a\u0645\u0627\u0644 \u062f\u06cc\u0633\u062a\u0631\u0633 \u062f\u0631 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0637\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f.",
   "interpretation": "\u0628\u0646\u062f \u0646\u0627\u0641 \u062f\u0648\u0631 \u06af\u0631\u062f\u0646 \u0628\u0633\u06cc\u0627\u0631 \u0634\u0627\u06cc\u0639 \u0627\u0633\u062a \u0648 \u0648\u062c\u0648\u062f \u0622\u0646 \u062f\u0631 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0628\u062f\u0648\u0646 \u0634\u0648\u0627\u0647\u062f \u062f\u06cc\u0633\u062a\u0631\u0633 \u062c\u0646\u06cc\u0646\u06cc \u06cc\u0627 \u0627\u0644\u06af\u0648\u06cc \u0636\u0631\u0628\u0627\u0646 \u0646\u0627\u0645\u0633\u0627\u0639\u062f\u060c \u0628\u0647\u200c\u062e\u0648\u062f\u06cc\u200c\u062e\u0648\u062f \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u0633\u0632\u0627\u0631\u06cc\u0646 \u0641\u0648\u0631\u06cc \u0646\u06cc\u0633\u062a\u061b \u0645\u0627\u0646\u06cc\u062a\u0648\u0631\u06cc\u0646\u06af \u062f\u0631 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0648 \u062a\u0635\u0645\u06cc\u0645\u200c\u06af\u06cc\u0631\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646\u06cc \u062f\u0631 \u0644\u062d\u0638\u0647 \u0645\u0646\u0627\u0633\u0628 \u0627\u0633\u062a \u0648 \u0642\u0637\u0639 \u062f\u0648\u0631\u0627\u0647\u06cc \u0628\u0627 \u0633\u0632\u0627\u0631\u06cc\u0646 \u0627\u0648\u0631\u0698\u0627\u0646\u0633 \u06cc\u0627 BPP \u0641\u0648\u0631\u06cc\u062a \u06cc\u0627 N-ST \u0631\u0648\u0632\u0627\u0646\u0647 \u0641\u0642\u0637 \u062f\u0631 \u0635\u0648\u0631\u062a \u0646\u0634\u0627\u0646\u0647\u200c\u0647\u0627\u06cc \u062f\u06cc\u0633\u062a\u0631\u0633 \u0645\u0639\u0646\u06cc \u067e\u06cc\u062f\u0627 \u0645\u06cc\u200c\u06a9\u0646\u062f.",
   "reasons": ["\u0633\u0632\u0627\u0631\u06cc\u0646 \u0641\u0648\u0631\u06cc \u0641\u0642\u0637 \u0628\u0647\u200c\u062e\u0627\u0637\u0631 nuchal cord \u0646\u0627\u062f\u0631\u0633\u062a \u0627\u0633\u062a.", "\u0633\u0632\u0627\u0631\u06cc\u0646 \u062f\u0631 \u0635\u0648\u0631\u062a BPP \u0646\u0631\u0645\u0627\u0644 \u062f\u0648\u0631\u0647\u0654 \u06a9\u0627\u0645\u0644 \u0646\u06cc\u0632 \u062a\u0648\u062c\u06cc\u0647 \u0646\u062f\u0627\u0631\u062f.", "NST \u0631\u0648\u0632\u0627\u0646\u0647 \u0641\u0642\u0637 \u062f\u0631 \u0634\u0631\u0627\u06cc\u0637 \u062e\u0627\u0635 \u0644\u0627\u0632\u0645 \u0627\u0633\u062a.", "\u0627\u062c\u0627\u0632\u0647\u0654 \u0645\u0633\u06cc\u0631 \u0637\u0628\u06cc\u0639\u06cc \u0628\u0627 \u067e\u0627\u06cc\u0634 \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 111): {
   "topic": "genitalWartsPregTreatment",
   "lead": "\u0632\u06af\u06cc\u0644\u200c\u0647\u0627\u06cc \u062a\u0646\u0627\u0633\u0644\u06cc \u0628\u0632\u0631\u06af/\u0645\u062a\u0639\u062f\u062f \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc: \u06a9\u0631\u0627\u06cc\u0648\u062a\u0631\u0627\u067e\u06cc/\u062d\u0630\u0641 \u0645\u06a9\u0627\u0646\u06cc\u06a9\u06cc \u0645\u062c\u0627\u0632\u0646\u062f\u061b \u067e\u0648\u062f\u0648\u0641\u06cc\u0644\u06cc\u0646 \u0648 \u0627\u06cc\u0645\u06cc\u200c\u06a9\u06cc\u0645\u0648\u062f \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0645\u0646\u0648\u0639\u200c\u0627\u0646\u062f.",
   "interpretation": "\u06a9\u0627\u0646\u062f\u06cc\u0644\u0648\u0645\u0627\u0647\u0627\u06cc \u0622\u06a9\u0648\u0645\u06cc\u0646\u0627\u062a\u0627 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0645\u06a9\u0646 \u0627\u0633\u062a \u0631\u0634\u062f \u06a9\u0646\u0646\u062f \u0648 \u0645\u062f\u06cc\u0631\u06cc\u062a \u062f\u0631\u0645\u0627\u0646\u06cc \u0628\u0627 \u062a\u0631\u0627\u0634\u06cc\u062f\u0646\u060c \u0644\u06cc\u0632\u0631\u060c \u06a9\u0631\u0627\u06cc\u0648 \u06cc\u0627 \u0646\u06cc\u062a\u0631\u0648\u0698\u0646 \u0645\u0627\u06cc\u0639 (\u06a9\u0631\u0627\u06cc\u0648\u062a\u0631\u0627\u067e\u06cc) \u062f\u0631 \u0645\u0648\u0627\u0631\u062f \u0644\u0627\u0632\u0645 \u0642\u0627\u0628\u0644\u200c\u0627\u0646\u062c\u0627\u0645 \u0627\u0633\u062a\u061b \u067e\u0648\u062f\u0648\u0641\u06cc\u0644\u06cc\u0646 \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u0633\u0645\u06cc\u062a \u0633\u06cc\u0633\u062a\u0645\u06cc\u06a9 \u0648 \u0627\u06cc\u0645\u06cc\u200c\u06a9\u06cc\u0645\u0648\u062f \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u0646\u0628\u0648\u062f \u062f\u0627\u062f\u0647\u0654 \u0627\u06cc\u0645\u0646\u06cc \u06a9\u0627\u0641\u06cc \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0646\u0628\u0627\u06cc\u062f \u0645\u0635\u0631\u0641 \u0634\u0648\u0646\u062f \u0648 \u0627\u0646\u062a\u0638\u0627\u0631 \u067e\u0633 \u0627\u0632 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0631 \u0636\u0627\u06cc\u0639\u0627\u062a \u0641\u0639\u0627\u0644 \u0686\u0646\u062f\u06af\u0627\u0646\u0647 \u06af\u0627\u0647\u06cc \u062a\u0635\u0645\u06cc\u0645 \u0631\u0627 \u0628\u0647 \u062a\u0623\u062e\u06cc\u0631 \u0645\u06cc\u200c\u0627\u0646\u062f\u0627\u0632\u062f \u0648\u0644\u06cc \u0647\u0645\u200c\u0627\u06a9\u0646\u0648\u0646 \u0628\u0647\u200c\u062e\u0635\u0648\u0635 \u062f\u0631 \u0641\u0648\u0631\u0634\u062a \u0648 \u0628\u0627 \u062a\u0627\u06cc\u067e \u067e\u0631\u062e\u0637\u0631 \u062f\u0631\u0645\u0627\u0646 \u0641\u0639\u0627\u0644 \u0645\u0646\u0637\u0642\u06cc\u200c\u062a\u0631 \u0627\u0633\u062a.",
   "reasons": ["\u067e\u0648\u062f\u0648\u0641\u06cc\u0644\u06cc\u0646 \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u0633\u0645\u06cc\u062a \u0633\u06cc\u0633\u062a\u0645\u06cc\u06a9 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a.", "\u0627\u06cc\u0645\u06cc\u200c\u06a9\u06cc\u0645\u0648\u062f \u062f\u0627\u062f\u0647\u0654 \u0627\u06cc\u0645\u0646\u06cc \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0646\u062f\u0627\u0631\u062f.", "\u06a9\u0631\u0627\u06cc\u0648\u062a\u0631\u0627\u067e\u06cc \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u0630\u06cc\u0631\u0641\u062a\u0647\u200c\u0634\u062f\u0647 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0635\u0628\u0631 \u062f\u0631 \u0636\u0627\u06cc\u0639\u0627\u062a \u0641\u0639\u0627\u0644 \u0645\u062a\u0639\u062f\u062f \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646\u0627\u0631\u06cc\u0648 \u0628\u0647 \u062a\u0623\u062e\u06cc\u0631 \u0645\u06cc\u200c\u0627\u0646\u062c\u0627\u0645\u062f."],
  },
  (28, 112): {
   "topic": "postmenoSimpleCystFollow",
   "lead": "\u06a9\u06cc\u0633\u062a \u0633\u0627\u062f\u0647 \u062c\u062f\u0627\u0631 \u0646\u0627\u0632\u06a9 \u0641\u0627\u0642\u062f \u0633\u067e\u062a\u0648\u0645 \u0628\u0627 \u0627\u0646\u062f\u0627\u0632\u0647\u0654 \u062d\u062f\u0648\u062f \u06f5 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631 \u062f\u0631 \u0632\u0646 \u06cc\u0627\u0626\u0633\u0647: \u0627\u06af\u0631 \u0639\u0644\u0627\u06cc\u0645 \u0646\u0628\u0627\u0634\u062f\u060c \u067e\u06cc\u06af\u06cc\u0631\u06cc \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc\u06a9 (\u06a9\u0646\u062a\u0631\u0644 \u062f\u0631 \u062f\u0648 \u0645\u0627\u0647) \u067e\u0630\u06cc\u0631\u0641\u062a\u0647\u200c\u0634\u062f\u0647 \u0648 \u0645\u0646\u0627\u0633\u0628 \u0627\u0633\u062a.",
   "interpretation": "\u062f\u0631 \u06cc\u0627\u0626\u0633\u0647\u060c \u0647\u0631 \u06a9\u06cc\u0633\u062a \u067e\u06cc\u0686\u06cc\u062f\u0647 \u0627\u062d\u062a\u0645\u0627\u0644 \u0628\u062f\u062e\u06cc\u0645\u06cc \u0628\u06cc\u0634\u200c\u062a\u0631 \u0627\u0633\u062a \u0627\u0645\u0627 \u06a9\u06cc\u0633\u062a\u200c\u0647\u0627\u06cc \u06a9\u0627\u0645\u0644\u0627\u064b \u0633\u0627\u062f\u0647 \u0648 \u062c\u062f\u0627\u0631 \u0646\u0627\u0632\u06a9 \u0628\u062f\u0648\u0646 \u0633\u067e\u062a\u0648\u0645 \u06a9\u0647 \u0627\u0646\u062f\u0627\u0632\u0647\u0654 \u0622\u0646\u200c\u0647\u0627 \u06a9\u0645\u062a\u0631 \u06cc\u0627 \u062d\u062f\u0648\u062f \u06f5 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631 \u0627\u0633\u062a (\u0628\u0647\u200c\u0648\u06cc\u0698\u0647 \u062f\u0631 \u063a\u06cc\u0627\u0628 \u0639\u0644\u0627\u06cc\u0645 \u0648 \u062f\u0631 \u0635\u0648\u0631\u062a \u06a9\u0645\u200c\u0631\u06cc\u0633\u06a9 \u0628\u0648\u062f\u0646 \u06a9\u0644\u06cc) \u06af\u0627\u0647 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646 \u0628\u0627 \u067e\u06cc\u06af\u06cc\u0631\u06cc \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc\u06a9 \u06a9\u0648\u062a\u0627\u0647\u200c\u0645\u062f\u062a \u06a9\u0631\u062f\u061b \u0627\u0642\u062f\u0627\u0645\u0627\u062a \u062c\u0631\u0627\u062d\u06cc (\u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc+BSO \u06cc\u0627 \u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u06a9\u06cc\u0633\u062a\u06a9\u062a\u0648\u0645\u06cc) \u062f\u0631 \u063a\u06cc\u0627\u0628 \u0634\u06a9 \u0628\u0647 \u0628\u062f\u062e\u06cc\u0645\u06cc \u06cc\u0627 \u0639\u0644\u0627\u06cc\u0645 \u0627\u0641\u0631\u0627\u0637 \u0627\u0633\u062a \u0648 \u0642\u0631\u0635 \u0636\u062f\u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0631 \u06cc\u0627\u0626\u0633\u0647 \u062c\u0627\u06cc\u06af\u0627\u0647\u06cc \u0646\u062f\u0627\u0631\u062f.",
   "reasons": ["\u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0648 \u0628\u0631\u062f\u0627\u0634\u062a\u0646 \u0647\u0631 \u062f\u0648 \u062a\u062e\u0645\u062f\u0627\u0646 \u062f\u0631 \u0627\u06cc\u0646 \u06cc\u0627\u0641\u062a\u0647\u0654 \u0633\u0627\u062f\u0647 \u0627\u0641\u0631\u0627\u0637 \u0627\u0633\u062a.", "\u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u06a9\u06cc\u0633\u062a\u06a9\u062a\u0648\u0645\u06cc \u0628\u0631\u0627\u06cc \u0647\u0631 \u06a9\u06cc\u0633\u062a \u0633\u0627\u062f\u0647\u0654 \u06cc\u0627\u0626\u0633\u0647 \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a.", "\u0642\u0631\u0635 \u0636\u062f\u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0631 \u0632\u0646\u0627\u0646 \u06cc\u0627\u0626\u0633\u0647 \u0645\u0639\u0642\u0648\u0644 \u0648 \u062a\u0648\u0635\u06cc\u0647\u200c\u0634\u062f\u0647 \u0646\u06cc\u0633\u062a.", "\u067e\u06cc\u06af\u06cc\u0631\u06cc \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc\u06a9 \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646\u0627\u0631\u06cc\u0648 \u067e\u0630\u06cc\u0631\u0641\u062a\u0646\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
}
